_TRANSPOSED_STEM = re.compile(
    r"_t(?:_tma[12])?(?:_s\d+)?(?:_box\d+)?(?:_skx)?(?:_sks)?(?:_sb[123])?(?:_b(?:f|g\d+))?(?:_so[flnd])?(?:_pd\d+)?(?:_sh\d+)?(?:_c1)?(?:_cg)?(?:_or)?(?:_pro\d+)?$"
)


def _transposed_template(template: str) -> bool:
    """``_t`` (transposed register epilogue) or ``_t_tma1`` / ``_t_tma2`` (round-14 transposed TMA-store epilogue),
    followed by the knob suffixes ``instance_symbol`` emits after the epilogue term (``_s<stages>``, ``_box<rows>``,
    ``_skx``, ``_sks`` / ``_sb<n>`` (rounds 18 / 19), ``_bf`` / ``_bg<n>``, ``_so<x>``, ``_pd<n>``, ``_sh<n>``, ``_c1``
    (round 19), ``_cg`` (round 21), ``_or`` (round 24), ``_pro<n>`` (round 33)) - e.g. the round-16 six-stage swapped MLA weight-gradient templates ``..._hee_t_tma1_s6``."""
    return _TRANSPOSED_STEM.search(template) is not None


def _key_knobs(knobs: dict) -> dict:
    """The instance-key keywords of a decoded template (``_template_knobs``): the knobs it sets, ``sk_exact`` as a flag
    and the planner's ``promote`` as the instance-key field ``promote_blocks``."""
    key_knobs = {k: v for k, v in knobs.items() if v is not None}
    key_knobs["sk_exact"] = bool(knobs["sk_exact"])
    key_knobs["promote_blocks"] = (
        cake_backend.K1_PROMOTE_BLOCKS if key_knobs.pop("promote", False) else 0
    )
    return key_knobs


def _nopro(template: str) -> str:
    """``template`` without the round-33 pair prologue / cleanup sync suffix (``_pro<n>``, the LAST knob suffix of every
    planned pair program since round 33) and the promoted-chunk token before it (``_kc128``: the planner's promoted twin
    of a long weight-gradient plan; no other chunk size is a program): the hand-written tests of rounds 15..27 assert
    their own round's program modulo that suffix; the round-33 tests assert the suffix itself, the promotion tests the
    token."""
    return re.sub(r"(?:_kc128)?_pro\d+$", "", template)


def _promoted(arch, plan, template):
    """The program the planner names for ``plan`` of the program ``template`` (without promotion) on ``arch``, by the
    rule of ``K1_PROMOTE_BLOCKS`` restated here: its promoted twin (``_kc128`` before ``_pro<n>``) where ``arch``
    registers the twin, the plan's longest segment holds more than ``K1_PROMOTE_MIN_SEGMENT`` K blocks and the row is
    no row of ``K1_PROMOTE_EXEMPT_ROWS``; else ``template``.  The measured rows of the tables below name the program
    without promotion: a registry that ships its twin runs the twin at their long token counts."""
    twin = re.sub(r"(_pro\d+)$", rf"_kc{cake_backend.K1_PROMOTE_BLOCKS}\1", template)
    if (
        twin != template
        and twin in _registered(arch)
        and cake_backend.segment_blocks(plan) > cake_backend.K1_PROMOTE_MIN_SEGMENT
        and not cake_backend._promote_exempt(arch, plan)
    ):
        return twin
    return template


def _rule_of(plan, sm_count):
    """The measured per-row rule the planner applied to ``plan`` (empty when the row has none or the
    registry fallback dropped it)."""
    if plan.rule_fallback:
        return {}
    return row_rule(
        ARCH_OF_SM[sm_count],
        plan.a_mn,
        plan.b_mn,
        plan.out_f32,
        plan.transposed_out,
        plan.L > 1,
        plan.N,
        plan.K,
        plan.M,
        sm_count=sm_count,
    )


def _registered(arch):
    """The K1 templates that are generated programs of ``arch`` in this tree (the export registers per architecture)."""
    return frozenset(
        t
        for t in cake_jit.KERNELS.get(arch, {})
        if t.startswith("dense_proj_det_gemm_")
    )


# the knob tokens ``instance_symbol`` emits after ``_ht`` (the transposed store, the epilogue, the tail policies, the
# raster forms, the load-warp prelude, the whole-tile tile resolve, the paced output stores and the pair prologue form)
_AFTER_HT = re.compile(
    r"^(t|tma\d+|s\d+|box\d+|skx|skf|sks|stt|sb\d|bf|bg\d+|so[a-z]|pd\d+|sh\d+|c1|cg|or|lw|mg|sw\d+|pro\d+)$"
)


def _rule_program(cake_template, rule):
    """The program the planner names for a row whose rule pins ``htail``: the Cake launcher's template with the
    ``_ht`` knob where the launcher's half-tail fit dropped it.  The planner's fit selects only the plan
    (``plan.htail_plan``); the program a rule names stays (the round-2 shapes tranche measured the K 5120 thin input
    gradients on that program with the whole-tile plan).  The knob is inserted at its ``instance_symbol`` position and
    checked through the backend's decoder: every other knob of the launcher's template is unchanged."""
    if not (rule and rule.get("htail")):
        return cake_template
    before = cake_backend._template_knobs(cake_template)
    if before is None or before["htail"]:
        return cake_template
    tokens = cake_template.split("_")
    at = next(
        (i for i in range(4, len(tokens)) if _AFTER_HT.match(tokens[i])), len(tokens)
    )
    with_ht = "_".join(tokens[:at] + ["ht"] + tokens[at:])
    after = cake_backend._template_knobs(with_ht)
    assert (
        after is not None and after["htail"] and {**after, "htail": False} == before
    ), (
        cake_template,
        with_ht,
    )
    return with_ht


def _eight_warp_program(cake_template, plan, arch):
    """The program the planner names for a row whose rule OF RECORD carries the eight-warp CTA form: the form's kn
    bf16 one-slot TMA-store program.  The rule is looked up from the plan's row identity on ``arch`` (``row_rule``)
    rather than read from the plan: under the registry fallback (before this tree registers the program) the plan
    carries neither the rule nor its form.  Every other row keeps the launcher's template."""
    form_rule = row_rule(
        arch,
        plan.a_mn,
        plan.b_mn,
        plan.out_f32,
        plan.transposed_out,
        plan.L > 1,
        plan.N,
        plan.K,
        plan.M,
    )
    if not form_rule.get("form"):
        return cake_template
    # the batched rows' head-interleaved raster where it divides the batch count, with the rule's store hint
    group = form_rule.get("batch_group") or 0
    raster = (
        dict(batch_group=group, store_hint=form_rule.get("store_hint", "none"))
        if group > 1 and plan.L % group == 0
        else {}
    )
    return cake_backend.instance_symbol(
        cake_backend.instance_key(
            a_mn=False, b_mn=True, epi="tma", slots=1, form=form_rule["form"], **raster
        )
    )


def _unserved_sync_store(arch, cake_template, plan):
    """The package-only synchronised TMA-store gate (``cake_backend._serves``): the launcher's plan is a
    synchronised stream-K bf16 TMA-store program (``_tma<slots>_sks``) whose epilogue the row's rule does not name
    (the bf16 short-K default), which the registry does not serve; ``plan`` is this package's plan of the same row."""
    knobs = cake_backend._template_knobs(cake_template)
    if not knobs or not (knobs["sk_sync"] and knobs["epi"] == "tma") or plan.out_f32:
        return False
    rule = cake_backend.row_rule(
        arch,
        plan.a_mn,
        plan.b_mn,
        plan.out_f32,
        plan.transposed_out,
        plan.L > 1,
        plan.N,
        plan.K,
        plan.M,
    )
    return "epi" not in rule


def _assert_mirrors_cake(plan, cake_template, where, arch, rule=None):
    """The plan is the Cake launcher's plan when that instance is a generated program of ``arch``; otherwise (the
    batched small-M swap on a tiny T outside the export contract, a measured rule whose template exists only for
    the contract's T, a synchronised TMA-store program the row reaches through the short-K epilogue default
    (``_unserved_sync_store``), or a default tail-T instance no contract row of this architecture produced -- all of which
    the Cake host JIT-compiles) this package's planner must have fallen back onto a generated program.  A rule that
    pins ``htail`` names its ``_ht`` program on every device and T (``_rule_program``); a rule of record that carries
    the eight-warp CTA form names its eight-warp program (``_eight_warp_program``: the launcher's plans carry no
    ``form``).  Where the launcher swapped such a row (the batched small-M swap on a tiny T: a transposed template),
    the eight-warp program serves only the caller's orientation, so the planner drops the swap and keeps the rule
    (``plan.swap_fallback``, the planner's first fallback)."""
    launcher_template = _rule_program(cake_template, rule)
    cake_template = _eight_warp_program(launcher_template, plan, arch)
    swap_dropped = cake_template != launcher_template and _transposed_template(
        _nopro(launcher_template)
    )
    registered = _registered(arch)
    assert registered <= EXPORTED_TEMPLATES, (
        arch,
        sorted(registered - EXPORTED_TEMPLATES),
    )
    if cake_template in registered and not _unserved_sync_store(
        arch, cake_template, plan
    ):
        assert plan.template == cake_template, (*where, plan.template)
        assert plan.swap_fallback == swap_dropped, (*where, swap_dropped)
        assert not (plan.rule_fallback or plan.knob_fallback), where
    else:
        assert plan.swap_fallback or plan.rule_fallback or plan.knob_fallback, (
            *where,
            cake_template,
            plan.template,
        )
        assert plan.template in registered, (*where, cake_template, plan.template)


def _registered_capabilities() -> str:
    """The compute capabilities this checkout registers generated programs for (the architectures of
    ``cake_jit.KERNELS``), spelled for the skip messages: ``10.0 or 10.7`` while ``build.json`` ships ``sm_100a`` and
    ``sm_107a`` builds, ``10.0, 10.3 or 10.7`` once the ``sm_103a`` programs register (see README)."""
    caps = [
        f"{major}.{minor}"
        for (major, minor), arch in sorted(
            cake_backend.SUPPORTED_COMPUTE_CAPABILITIES.items()
        )
        if arch in cake_jit.KERNELS
    ]
    return (
        " or ".join(caps)
        if len(caps) <= 2
        else ", ".join(caps[:-1]) + " or " + caps[-1]
    )


def _device_supported() -> bool:
    """A device this checkout registers generated programs for (an architecture of ``cake_jit.KERNELS``: compute
    capability ``_registered_capabilities()``; see README)."""
    return torch.cuda.is_available() and generated_program_available(
        torch.device("cuda")
    )


def _require_program(template: str):
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    if not generated_program_available(torch.device("cuda"), template):
        pytest.skip(f"generated instance {template!r} not registered for this device")


def _registered_knobs(v, *candidates):
    """The first planner knob set (in order) whose planned instance the export registered for this device.
    The per-arch export only ships the instances its measured rules route to, so a test that pins a tile
    family takes whichever family's instance this device has; skips when none is registered."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    templates = [_plan_template(v, **knobs) for knobs in candidates]
    for knobs, template in zip(candidates, templates, strict=True):
        if generated_program_available(torch.device("cuda"), template):
            return knobs
    pytest.skip(
        f"none of the generated instances {templates!r} is registered for this device"
    )


def _sm_count() -> int:
    return int(torch.cuda.get_device_properties(0).multi_processor_count)


def _l2_bytes() -> int:
    return device_l2_bytes(torch.device("cuda", 0))


