def test_promoted_twin_gpu_cases_cover_every_twin():
    """``PROMOTED_TWIN_GPU_CASES`` and ``PROMOTED_GPU_CASES`` together launch every shipped twin: the eight forms
    above by their knobs, the 64-row 128- and 256-wide programs through the planner."""
    forced = {case[0] for case in PROMOTED_TWIN_GPU_CASES}
    planned = {
        "dense_proj_det_gemm_nn_n256_m64_hen_t_kc128_pro15",
        "dense_proj_det_gemm_nn_n128_m64_hen_t_kc128_pro15",
    }
    assert len(forced) == len(PROMOTED_TWIN_GPU_CASES) and not forced & planned
    assert forced | planned == set(PROMOTED_TWINS)
    for twin, *_, arches in PROMOTED_TWIN_GPU_CASES:
        assert arches and set(arches) <= set(PROMOTED_TWINS[twin]), twin
        knobs = cake_backend._template_knobs(twin)
        assert knobs is not None and knobs["promote"] is True, twin


#: The SM count of a part of each architecture the CPU plan check plans for.
_FORCED_TWIN_SM_COUNT = {"sm_100a": 148, "sm_103a": 152, "sm_107a": 212}


def _forced_twin_knobs(twin):
    """The knobs of ``twin``'s symbol the prepare call takes (``promote=True`` among them); the rest (``kser``,
    ``sk_first``, ``lw``, ``mg``, ``sw``) are off in every twin."""
    knobs = cake_backend._template_knobs(twin)
    assert knobs is not None and knobs["promote"] is True, twin
    takes = inspect.signature(cake_dense_gemm_det_train_projection_prepare).parameters
    assert not any(v for k, v in knobs.items() if k not in takes), (twin, knobs)
    return {k: v for k, v in knobs.items() if k in takes}


def test_forced_twin_cases_plan_their_twin():
    """On every architecture of a ``PROMOTED_TWIN_GPU_CASES`` row, the twin's knobs plan exactly the twin for the
    row's weight gradient, with a longest segment of more than one chunk: the GPU test's premise, checked without a
    device."""
    for twin, d_out, d_in, T, arches in PROMOTED_TWIN_GPU_CASES:
        knobs = _forced_twin_knobs(twin)
        for arch in arches:
            G = torch.empty(T, d_out, dtype=torch.bfloat16)
            X = torch.empty(T, d_in, dtype=torch.bfloat16)
            A, B, transposed = wgrad_views(G, X, arch=arch)
            plan = cake_dense_gemm_det_train_projection_plan(
                A,
                B,
                torch.empty(d_out, d_in, dtype=torch.bfloat16),
                sm_count=_FORCED_TWIN_SM_COUNT[arch],
                l2_bytes=L2_BYTES,
                transposed_out=transposed,
                arch=arch,
                **knobs,
            )[0]
            assert plan.template == twin, (arch, twin, plan.template)
            assert plan.promote_blocks == cake_backend.K1_PROMOTE_BLOCKS, (arch, twin)
            assert cake_backend.segment_blocks(plan) > cake_backend.K1_PROMOTE_BLOCKS, (
                arch,
                twin,
            )


@pytest.mark.parametrize(
    "case",
    PROMOTED_TWIN_GPU_CASES,
    ids=lambda c: f"{c[0].removeprefix('dense_proj_det_gemm_')}-{c[1]}x{c[2]}-T{c[3]}",
)
def test_gpu_promoted_twin_forms(case):
    """On each architecture of ``case``, the twin ``case[0]`` forced by its knobs (``promote=True`` among them) plans
    itself for the weight gradient of ``case``, with a longest segment of more than one chunk; it meets the naive BF16
    tier against FP64 over the judge's draws, each launch into a NaN-poisoned output (three on the first draw), and
    writes the same bits on three more launches."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    device = torch.device("cuda")
    arch = arch_for(device)
    twin, d_out, d_in, T, arches = case
    if arch not in arches:
        pytest.skip(f"a case of {list(arches)}; the device is {arch}")
    knobs = _forced_twin_knobs(twin)
    G, X = _d1_wgrad_operands(T, d_out, d_in, SEED, device)
    A, B, transposed = wgrad_views(G, X, arch=arch)
    out = torch.full((d_out, d_in), float("nan"), dtype=torch.bfloat16, device=device)
    prepared = cake_dense_gemm_det_train_projection_prepare(
        A, B, out, transposed_out=transposed, **knobs
    )
    plan = prepared.plan
    assert prepared.template == twin, (prepared.template, twin)
    assert plan.promote_blocks == cake_backend.K1_PROMOTE_BLOCKS, twin
    assert cake_backend.segment_blocks(plan) > cake_backend.K1_PROMOTE_BLOCKS, twin

    def draw(s):
        for t, value in zip(
            (G, X), _d1_wgrad_operands(T, d_out, d_in, s, device), strict=True
        ):
            t.copy_(value)
        nan_fill([out])
        return SimpleNamespace(G=G, X=X)

    def launch(_inputs):
        prepared.launch()
        torch.cuda.synchronize()
        return {"promoted": out}

    def product(v, dtype):
        return {"promoted": torch.matmul(v.G.to(dtype).t(), v.X.to(dtype))}

    judge_gemm(
        None,
        seed=SEED,
        draw=draw,
        launch=launch,
        product=product,
        launches=3,
        poison=lambda v: [out],
    )
    # run to run: the same bits on every launch of the last draw's inputs
    runs = []
    for _ in range(3):
        nan_fill([out])
        prepared.launch()
        torch.cuda.synchronize()
        runs.append(out.clone())
    assert all(torch.equal(run, runs[0]) for run in runs[1:])


# The GB T-exact serpentine-K rules: (arch, B MN-major, N, K) -> (the T of the exact keys, the program on the 76-pair parts, the
# program without ``kser``).  Each key names the T 16231 key's program of the row with ``kser`` 76 (at T 16172; at the T of
# the row's round-9 / round-10 keys the key's own rule gains ``kser`` 76); the wave guard keeps it on
# the 152-SM parts only (76 CTA pairs), every other part plans the program without it.
GB_T_EXACT_KSER_ROWS = {
    ("sm_103a", False, 4096, 12288): (
        (16172, 16384),
        "dense_proj_det_gemm_kk_n256_m256_ht_cg_or_ks76_pro7",
        "dense_proj_det_gemm_kk_n256_m256_ht_cg_or_pro7",
    ),
    ("sm_103a", True, 4096, 12288): (
        (16172, 16231, 16384),
        "dense_proj_det_gemm_kn_n256_m256_ht_cg_or_ks76_pro7",
        "dense_proj_det_gemm_kn_n256_m256_ht_cg_or_pro7",
    ),
}
GB_T_EXACT_KSER_KEYS = sorted(
    (arch, False, b_mn, False, False, False, N, K, T)
    for (arch, b_mn, N, K), (Ts, _template, _plain) in GB_T_EXACT_KSER_ROWS.items()
    for T in Ts
)


def test_kser_instance_key_symbol_and_refusals():
    """``kser`` is instance-key field 38 (symbol ``_ks<P>`` between ``_sw<n>`` and ``_pro<n>``); 0 renders the key and symbol of
    the program without it; the single-CTA form, the exact / tail-first / synchronised splits, the transposed staging, the
    whole-tile tile resolve, a batch raster, the eight-warp form and a negative count are refused; the symbol decodes back."""
    tall = dict(
        a_mn=False, b_mn=True, cta_rows=256, ovr=True, htail=True, cgrp=True, pro=7
    )
    on, off = instance_key(**tall, kser=76), instance_key(**tall)
    assert len(on) == 39 and on[37] == 76 and off[37] == 0 and on[:37] == off[:37]
    assert instance_symbol(on) == "dense_proj_det_gemm_kn_n256_m256_ht_cg_or_ks76_pro7"
    assert instance_symbol(off) == "dense_proj_det_gemm_kn_n256_m256_ht_cg_or_pro7"
    assert cake_backend._template_knobs(instance_symbol(on))["kser"] == 76
    assert cake_backend._template_knobs(instance_symbol(off))["kser"] == 0
    for bad in (
        dict(a_mn=False, b_mn=True, kser=-1),
        dict(a_mn=False, b_mn=True, cta1=True, kser=76),
        dict(a_mn=False, b_mn=True, sk_exact=True, kser=76),
        dict(a_mn=False, b_mn=True, sk_exact=True, sk_first=True, kser=76),
        dict(a_mn=False, b_mn=True, sk_sync=True, kser=76),
        dict(a_mn=True, b_mn=True, out_t=True, stt=True, kser=76),
        dict(a_mn=False, b_mn=True, mg=True, pro=4, kser=76),
        dict(a_mn=False, b_mn=True, batch_group=8, kser=76),
    ):
        with pytest.raises(ValueError, match="kser"):
            instance_key(**bad)


@pytest.mark.parametrize("arch", ["sm_103a"])
def test_gb_t_exact_kser_rules_plan_their_programs(arch, monkeypatch):
    """The GB T-exact serpentine-K rules (sm_103a: the 12288 -> 4096 forward at T 16172 / 16384 and
    the 4096 -> 12288 input gradient at T 16172 / 16231 / 16384) plan their ``_ks76`` program on the 152-SM part
    and the program without ``kser`` on the 148- and 160-SM parts
    (the wave guard); on every part the plan is the plan of the key's rule without ``kser`` but for the program (whole K per
    output tile, the same K partitions, raster group and grid), and T +- 1 plan the row's plan without the key."""
    monkeypatch.setattr(cake_backend, "_DUMMIES", {})
    keys = sorted(
        key for key in ROW_RULES if key[0] == arch and "kser" in ROW_RULES[key]
    )
    assert keys == [key for key in GB_T_EXACT_KSER_KEYS if key[0] == arch]
    registered = _registered(arch)
    for key in keys:
        _arch, _a_mn, b_mn, _f32, _out_t, _batched, N, K, T = key
        _Ts, template, plain_template = GB_T_EXACT_KSER_ROWS[(arch, b_mn, N, K)]
        assert template in registered and plain_template in registered, key
        rule = dict(ROW_RULES[key])
        assert rule.pop("kser") == 76
        for sm_count in (148, 152, 160):
            kw = dict(sm_count=sm_count, l2_bytes=L2_BYTES, arch=arch, _fallback=False)
            v = _class_views("kn" if b_mn else "kk", False, False, T, N, K)
            plan, *_ = cake_dense_gemm_det_train_projection_plan(
                v["A"], v["B"], v["out"], **kw
            )
            assert not (
                plan.rule_fallback or plan.knob_fallback or plan.swap_fallback
            ), key
            assert _whole_k(plan), (key, sm_count)
            if sm_count == 152:
                assert (plan.template, plan.kser) == (template, 76), (
                    key,
                    sm_count,
                    plan.template,
                )
            else:
                assert (plan.template, plan.kser) == (plain_template, 0), (
                    key,
                    sm_count,
                    plan.template,
                )
            with monkeypatch.context() as m:
                m.setitem(ROW_RULES, key, rule)
                v = _class_views("kn" if b_mn else "kk", False, False, T, N, K)
                without, *_ = cake_dense_gemm_det_train_projection_plan(
                    v["A"], v["B"], v["out"], **kw
                )
            assert without.template == plain_template and without.kser == 0, (
                key,
                sm_count,
            )
            assert (
                plan.group_m,
                plan.grid,
                plan.k_blocks,
                plan.num_full,
                plan.sk_units,
                plan.htail_plan,
            ) == (
                without.group_m,
                without.grid,
                without.k_blocks,
                without.num_full,
                without.sk_units,
                without.htail_plan,
            ), (key, sm_count)
            for t in (T - 1, T + 1):
                v = _class_views("kn" if b_mn else "kk", False, False, t, N, K)
                near, *_ = cake_dense_gemm_det_train_projection_plan(
                    v["A"], v["B"], v["out"], **kw
                )
                with monkeypatch.context() as m:
                    m.delitem(ROW_RULES, key)
                    v = _class_views("kn" if b_mn else "kk", False, False, t, N, K)
                    far, *_ = cake_dense_gemm_det_train_projection_plan(
                        v["A"], v["B"], v["out"], **kw
                    )
                assert near.kser == 0 and _plan_signature(near) == _plan_signature(
                    far
                ), (key, t)


@pytest.mark.parametrize(
    "key",
    GB_T_EXACT_KSER_KEYS,
    ids=lambda key: f"{key[0]}-{'kn' if key[2] else 'kk'}-{key[6]}x{key[7]}-T{key[8]}",
)
def test_gb_t_exact_kser_rows_match_fp64_and_repeat_bitwise(
    key, monkeypatch, record_property
):
    """Each GB T-exact serpentine-K row of the device's architecture runs its program at its T with whole K per output
    tile, bitwise equal over repeated launches into NaN and a second prepare; on the 152-SM part the program is the
    ``_ks76`` one and the plan without ``kser`` runs the program without it, elsewhere the program is the one without
    ``kser``.  Each output is judged against the FP64 oracle beside the naive BF16 tier over the draws.  A key of
    another architecture is skipped."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    arch, _a_mn, b_mn, _f32, _out_t, _batched, N, K, T = key
    device = torch.device("cuda")
    if arch != arch_for(device):
        pytest.skip(f"a {arch} key; the device is {arch_for(device)}")
    A, B = _d1_gb_operands(T, N, K, b_mn, SEED, device)
    _Ts, template, plain_template = GB_T_EXACT_KSER_ROWS[(arch, b_mn, N, K)]
    pairs = torch.cuda.get_device_properties(device).multi_processor_count // 2
    want = template if pairs == 76 else plain_template
    _require_program(want)
    out = torch.full((T, N), float("nan"), dtype=torch.bfloat16, device=device)
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
    prepared = cake_dense_gemm_det_train_projection_prepare(A, B, out)
    assert prepared.template == want, prepared.template
    assert _whole_k(prepared.plan)
    launches = {"out": (prepared, out)}
    if pairs == 76:
        rule = dict(ROW_RULES[key])
        rule.pop("kser")
        plain_out = torch.full_like(out, float("nan"))
        with monkeypatch.context() as m:
            m.setitem(ROW_RULES, key, rule)
            cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
            plain = cake_dense_gemm_det_train_projection_prepare(A, B, plain_out)
        assert plain.template == plain_template, plain.template
        launches["out_without_kser"] = (plain, plain_out)

    def draw(s):
        # the draw's operands, written into the tensors the prepared launches are bound to
        for t, value in zip(
            (A, B), _d1_gb_operands(T, N, K, b_mn, s, device), strict=True
        ):
            t.copy_(value)
        nan_fill([output for _, output in launches.values()])
        return SimpleNamespace(A=A, B=B)

    def launch(_inputs):
        for launched, _ in launches.values():
            launched.launch()
        torch.cuda.synchronize()
        return {name: output for name, (_, output) in launches.items()}

    def product(v, dtype):
        expected = torch.matmul(v.A.to(dtype), v.B.to(dtype))
        return dict.fromkeys(launches, expected)

    judge_gemm(record_property, seed=SEED, draw=draw, launch=launch, product=product)
    first = out.clone()
    for _ in range(3):
        out.fill_(float("nan"))
        prepared.launch()
        torch.cuda.synchronize()
        assert torch.equal(out.view(torch.int16), first.view(torch.int16)), key
    again_out = torch.full_like(out, float("nan"))
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
    again = cake_dense_gemm_det_train_projection_prepare(A, B, again_out)
    again.launch()
    torch.cuda.synchronize()
    assert torch.equal(again_out.view(torch.int16), first.view(torch.int16)), key


