def test_strided_views_and_storage_offsets_match_fp64_reference(record_property):
    """A forward on strided views with storage offsets and the swapped small-N weight gradient with the transposed
    fp32 store into a padded buffer: both outputs judged against the naive BF16 tier over 32 draws written into the
    bound buffers; the padding of both output buffers stays NaN."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    device = torch.device("cuda")
    g = torch.Generator(device=device).manual_seed(SEED + 2)
    T, K, N = 301, 704, 264
    # A: a column slice inside a wider buffer starting at a 16-byte aligned offset; B: a row slice of a taller
    # weight; out: a slice inside a larger buffer with a padded row stride
    a_buf = (torch.randn(T, K + 64, device=device, generator=g)).to(torch.bfloat16)
    A = a_buf[:, 8 : 8 + K]
    w_buf = (torch.randn(N + 16, K, device=device, generator=g) * K**-0.5).to(
        torch.bfloat16
    )
    W = w_buf[16:]
    out_buf = torch.full(
        (T + 3, N + 24), float("nan"), device=device, dtype=torch.bfloat16
    )
    out = out_buf[3:, 8 : 8 + N]
    _require_program(_plan_template(dict(A=A, B=W.t(), out=out)))
    prepared = cake_dense_gemm_det_train_projection_prepare(A, W.t(), out)
    # the swapped small-N weight gradient X.T @ G (both operands MN-major) with the transposed fp32
    # store into a [N, K] output that sits inside a wider buffer (padded row stride)
    Nf = 96
    Gs = torch.randn(T, Nf, device=device, generator=g).to(torch.bfloat16)
    out_t_buf = torch.full(
        (Nf, K + 8), float("nan"), device=device, dtype=torch.float32
    )
    out_t = out_t_buf[:, :K]
    # (the 128-row fp32 transposed instance on sm_107a, the 64-row one on sm_100a: round 9 routes the sm_100a
    # small-N weight gradients to the 64-row family, so only that family's instance is exported there)
    v_t = dict(A=A.t(), B=Gs, out=out_t, transposed=True)
    knobs_t = _registered_knobs(v_t, {}, dict(cta_rows=64))
    prepared_t = cake_dense_gemm_det_train_projection_wgrad_prepare(
        Gs, A, out_t, **knobs_t
    )
    assert prepared_t.plan.transposed_out and prepared_t.template == _plan_template(
        v_t, **knobs_t
    )
    assert _nopro(prepared_t.template).startswith(
        "dense_proj_det_gemm_nn_n128"
    ) and _nopro(prepared_t.template).endswith("_f32_t")
    assert (
        prepared_t.plan.l2_bytes == _l2_bytes()
        and prepared_t.plan.sm_pairs == _sm_count() // 2
    )

    def draw(seed):
        gen = torch.Generator(device=device).manual_seed(seed)
        a_buf.copy_(
            torch.randn(T, K + 64, device=device, generator=gen).to(torch.bfloat16)
        )
        w_buf.copy_(
            (torch.randn(N + 16, K, device=device, generator=gen) * K**-0.5).to(
                torch.bfloat16
            )
        )
        Gs.copy_(torch.randn(T, Nf, device=device, generator=gen).to(torch.bfloat16))
        nan_fill([out, out_t])
        return A, W, Gs

    def launch(_):
        prepared.launch()
        prepared_t.launch()
        torch.cuda.synchronize()
        return {"out": out, "out_t": out_t}

    def product(operands, dtype):
        a, w, gs = (t.to(dtype) for t in operands)
        return {"out": torch.matmul(a, w.t()), "out_t": torch.matmul(gs.t(), a)}

    judge_gemm(
        record_property, seed=SEED + 2, draw=draw, launch=launch, product=product
    )
    assert bool(torch.isnan(out_buf[:3].float()).all()) and bool(
        torch.isnan(out_buf[3:, :8].float()).all()
    )
    assert bool(torch.isnan(out_buf[3:, 8 + N :].float()).all())
    assert bool(torch.isnan(out_t_buf[:, K:]).all())


def test_prepared_gemm_launches_without_allocation_and_is_deterministic(
    record_property,
):
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    # a swapped weight gradient on a half-width synthetic row (N = 32, K = 3072, T = 1001): stream-K "auto"
    # two-part split of a single partial wave with the deterministic in-kernel fixup.  The round-9 rules route
    # the GLM small-N weight gradients to whole tiles on sm_100a (64-row family: 48 tiles, which 74 pairs cannot
    # split), so the split is pinned on this row with whichever of the 64-row / 128-row instances this device's
    # export registered: the 64-row instance plans 24 pair tiles of 128 rows (sm_100a), the 128-row instance 12
    # pair tiles of 256 rows (sm_107a); the expectation follows the registered instance's tile height.
    device = torch.device("cuda")
    g = torch.Generator(device=device).manual_seed(SEED + 3)
    T, K, N = 1001, 3072, 32
    X = torch.randn(T, K, device=device, generator=g).to(torch.bfloat16)
    G = torch.randn(T, N, device=device, generator=g).to(torch.bfloat16)
    out = torch.empty(N, K, device=device, dtype=torch.bfloat16)
    v = dict(A=X.t(), B=G, out=out, transposed=True)
    knobs = _registered_knobs(v, dict(cta_rows=64), dict(cta_rows=128))
    prepared = cake_dense_gemm_det_train_projection_wgrad_prepare(G, X, out, **knobs)
    pair_tiles = prepared.plan.M // (
        2 * prepared.plan.cta_rows
    )  # 24 (64-row instance) or 12 (128-row instance)
    assert prepared.plan.transposed_out and pair_tiles in (12, 24)
    assert prepared.plan.pair_tiles == pair_tiles
    if (
        prepared.plan.sm_pairs >= 2 * pair_tiles
    ):  # one partial wave whose halves fit the pairs: every tile in two parts
        assert (prepared.plan.tail_tiles, prepared.plan.sk_units) == (
            pair_tiles,
            2 * pair_tiles,
        )

    def draw(seed):
        gen = torch.Generator(device=device).manual_seed(seed)
        X.copy_(torch.randn(T, K, device=device, generator=gen).to(torch.bfloat16))
        G.copy_(torch.randn(T, N, device=device, generator=gen).to(torch.bfloat16))
        nan_fill([out])
        return X, G

    def launch(_):
        result = prepared.launch()
        torch.cuda.synchronize()
        return {"out": result.t()}

    def product(operands, dtype):
        x, grad = (t.to(dtype) for t in operands)
        return {"out": torch.matmul(x.t(), grad)}

    judge_gemm(
        record_property, seed=SEED + 3, draw=draw, launch=launch, product=product
    )
    # a relaunch on the last draw's operands into NaN: no allocation, the same bits
    first = out.clone()
    nan_fill([out])
    torch.cuda.synchronize()
    before = torch.cuda.memory_stats()
    prepared.launch()
    torch.cuda.synchronize()
    after = torch.cuda.memory_stats()
    assert after["allocation.all.allocated"] == before["allocation.all.allocated"]
    assert torch.equal(first, out)


def test_convenience_path_reuses_its_planned_launch_without_allocation(
    record_property,
):
    """The convenience forward plans one entry for a geometry: its output is judged against the naive BF16 tier
    over 32 draws of new tensors of that geometry, which all launch the one cached entry.  A call of new tensors
    allocates nothing; on the last draw's operands the same call, the call on another stream (its own entry and
    arena) and the prepared launch of the same binding each write the bits of the judged output into NaN."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    device = torch.device("cuda")
    g = torch.Generator(device=device).manual_seed(SEED + 6)
    T, K, N = (
        257,
        6144,
        576,
    )  # the kv_a forward row (register epilogue, K-major operands)
    X = torch.randn(T, K, device=device, generator=g).to(torch.bfloat16)
    W = (torch.randn(N, K, device=device, generator=g) * K**-0.5).to(torch.bfloat16)
    out = torch.empty(T, N, device=device, dtype=torch.bfloat16)
    _require_program(_device_template(dict(A=X, B=W.t(), out=out)))
    facts = cake_backend.device_facts(device)
    assert facts is cake_backend.device_facts(torch.device("cuda", facts.index))
    assert (facts.sm_count, facts.l2_bytes) == (_sm_count(), _l2_bytes())
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()

    def draw(seed):
        gen = torch.Generator(device=device).manual_seed(seed)
        return SimpleNamespace(
            X=torch.randn(T, K, device=device, generator=gen).to(torch.bfloat16),
            W=(torch.randn(N, K, device=device, generator=gen) * K**-0.5).to(
                torch.bfloat16
            ),
            out=torch.full((T, N), float("nan"), device=device, dtype=torch.bfloat16),
        )

    def launch(d):
        cake_backend.cake_dense_gemm_det_train_projection_forward(d.X, d.W, d.out)
        torch.cuda.synchronize()
        return {"out": d.out}

    def product(d, dtype):
        return {"out": torch.matmul(d.X.to(dtype), d.W.to(dtype).t())}

    last = judge_gemm(
        record_property, seed=SEED + 6, draw=draw, launch=launch, product=product
    )
    # every draw's new tensors of the one geometry launched the one planned entry
    assert len(cake_backend._K1_CACHE) == 1
    X, W, out = last.X, last.W, last.out
    first = out.clone()
    # new tensors of the same geometry hit the cached plan: no planning, no allocation (``out`` is given)
    X2 = torch.randn(T, K, device=device, generator=g).to(torch.bfloat16)
    out2 = torch.empty_like(out)
    before = torch.cuda.memory_stats()
    cake_backend.cake_dense_gemm_det_train_projection_forward(X2, W, out2)
    torch.cuda.synchronize()
    after = torch.cuda.memory_stats()
    assert after["allocation.all.allocated"] == before["allocation.all.allocated"]
    assert len(cake_backend._K1_CACHE) == 1
    # the same call again, into NaN: the same bits
    nan_fill([out])
    assert torch.equal(
        cake_backend.cake_dense_gemm_det_train_projection_forward(X, W, out), first
    )
    assert len(cake_backend._ARENAS) == 1
    # another stream never shares an entry (nor its workspace arena); it writes the same bits into NaN
    nan_fill([out2])
    torch.cuda.synchronize()
    with torch.cuda.stream(torch.cuda.Stream(device=device)):
        cake_backend.cake_dense_gemm_det_train_projection_forward(X, W, out2)
    torch.cuda.synchronize()
    assert len(cake_backend._K1_CACHE) == 2 and torch.equal(out2, first)
    first_entry, second_entry = cake_backend._K1_CACHE.values()
    assert (
        first_entry.arena is not second_entry.arena and len(cake_backend._ARENAS) == 2
    )
    assert {e.arena.key for e in (first_entry, second_entry)} == set(
        cake_backend._ARENAS
    )
    # the prepared path of the same binding gives the same bits, into NaN
    nan_fill([out2])
    prepared = cake_dense_gemm_det_train_projection_prepare(X, W.t(), out2)
    assert (
        prepared.template == next(iter(cake_backend._K1_CACHE.values())).plan.template
    )
    assert torch.equal(prepared.launch(), first)


def test_convenience_path_replays_a_stream_k_row_bit_exact(record_property):
    """The cached entry carves the stream-K workspace and the slice counters out of the arena of its device
    and stream: every later call of the same geometry reuses them without a memset (the kernel resets every
    counter it uses).  Its output is judged against the naive BF16 tier over 32 draws of new tensors of that
    geometry (``out`` allocated by each call); on the last draw's operands a call into a NaN-filled ``out`` stays
    allocation-free and reproduces the judged result bit for bit."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    device = torch.device("cuda")
    g = torch.Generator(device=device).manual_seed(SEED + 7)
    T, K, N = (
        1001,
        3072,
        32,
    )  # the swapped small-N weight gradient of the prepared-launch test
    X = torch.randn(T, K, device=device, generator=g).to(torch.bfloat16)
    G = torch.randn(T, N, device=device, generator=g).to(torch.bfloat16)
    v = dict(
        A=X.t(),
        B=G,
        out=torch.empty(N, K, device=device, dtype=torch.bfloat16),
        transposed=True,
    )
    knobs = _registered_knobs(v, dict(cta_rows=64), dict(cta_rows=128))
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()

    def draw(seed):
        gen = torch.Generator(device=device).manual_seed(seed)
        return SimpleNamespace(
            X=torch.randn(T, K, device=device, generator=gen).to(torch.bfloat16),
            G=torch.randn(T, N, device=device, generator=gen).to(torch.bfloat16),
            out=None,
        )

    def launch(d):
        d.out = cake_backend.cake_dense_gemm_det_train_projection_wgrad(
            d.G, d.X, **knobs
        )  # ``out`` allocated here
        torch.cuda.synchronize()
        return {"out": d.out.t()}

    def product(d, dtype):
        return {"out": torch.matmul(d.X.to(dtype).t(), d.G.to(dtype))}

    last = judge_gemm(
        record_property, seed=SEED + 7, draw=draw, launch=launch, product=product
    )
    X, G, out1 = last.X, last.G, last.out
    assert len(cake_backend._K1_CACHE) == 1
    entry = next(iter(cake_backend._K1_CACHE.values()))
    # the weight-gradient swap is the caller's (``wgrad_views`` -> ``transposed_out``); the batched small-M
    # swap of the planner (``entry.swapped``) does not apply to a 2-D row
    assert entry.plan.transposed_out and not entry.swapped
    out2 = torch.empty_like(out1)
    nan_fill([out2])
    torch.cuda.synchronize()
    before = torch.cuda.memory_stats()
    cake_backend.cake_dense_gemm_det_train_projection_wgrad(G, X, out2, **knobs)
    torch.cuda.synchronize()
    after = torch.cuda.memory_stats()
    assert after["allocation.all.allocated"] == before["allocation.all.allocated"]
    assert len(cake_backend._K1_CACHE) == 1 and torch.equal(out1, out2)
    counters = entry.arena.buffers["k1_counters"]
    assert counters.numel() >= entry.plan.counters_alloc_u32
    assert entry.arena.buffers["k1_ws"].numel() >= max(entry.plan.ws_f32_elems, 1)
    if entry.plan.sk_units:
        # the whole shared counter buffer is back at zero when the launch completes (the zero contract every
        # entry of the arena relies on), not only the slice counters this launch used
        assert int(torch.count_nonzero(counters.view(torch.int32))) == 0
    # a different knob set is a different entry (``_registered_knobs`` picked the registered family)
    assert cake_backend.convenience_key(
        0, 0, (True, ("cta_rows", 64), ("sk", "auto")), G, X, out1
    ) != cake_backend.convenience_key(
        0, 0, (True, ("cta_rows", 128), ("sk", "auto")), G, X, out1
    )


class _RecordingModule:
    """A loaded module stand-in: its entry records ``(module name, arguments)`` (CPU binding tests)."""

    def __init__(self, name: str, calls: list):
        self.name, self.calls = name, calls

    def __getattr__(self, entry):
        return lambda *args: self.calls.append((self.name, args))


def _cpu_k1_entry_points(monkeypatch, arch="sm_103a"):
    """CPU stand-ins for the K1 entry points (nothing is loaded or launched): the device facts of a 152-SM part, the
    device and the raw stream 7 of every call, the dummies on the CPU, stand-in modules whose entries record their
    arguments, the FFI conversion as the identity and fresh caches.  Returns ``(calls, made)``: the recorded launches
    and the stream contexts made."""
    calls, made = [], []
    facts = cake_backend.DeviceFacts(
        index=0, arch=arch, sm_count=152, l2_bytes=126 << 20
    )
    monkeypatch.setattr(cake_backend.tvm_ffi, "from_dlpack", lambda t, **_: t)
    monkeypatch.setattr(cake_backend, "device_facts", lambda device=None: facts)
    monkeypatch.setattr(cake_backend, "arch_for", lambda device=None: arch)
    monkeypatch.setattr(cake_backend, "require_arch", lambda device: arch)
    monkeypatch.setattr(cake_backend, "_same_cuda_device", lambda A, B, out: out.device)
    monkeypatch.setattr(cake_backend, "_cuda_index", lambda device=None: 0)
    monkeypatch.setattr(cake_backend, "_current_raw_stream", lambda index: 7)
    monkeypatch.setattr(
        cake_backend, "_dummy_key", lambda device, dtype, tag=None: ("cpu", dtype, tag)
    )
    monkeypatch.setattr(cake_backend, "_DUMMIES", {})

    def stream_context(index, raw=None):
        made.append((threading.get_ident(), index, raw))
        return contextlib.nullcontext()

    monkeypatch.setattr(cake_backend, "_ffi_stream_context", stream_context)
    monkeypatch.setattr(
        cake_backend,
        "load_cake_dense_projection_det_gemm_module",
        lambda name, a: _RecordingModule(name, calls),
    )
    for name in ("_K1_CACHE", "_K2_CACHE", "_SWAP_CACHE", "_K1_BOUND_CACHE"):
        monkeypatch.setattr(cake_backend, name, OrderedDict())
    monkeypatch.setattr(cake_backend, "_ARENAS", {})
    monkeypatch.setattr(cake_backend, "_STREAM_CONTEXTS", {})
    return calls, made


def _same_launch_arguments(got: tuple, want: tuple, module_name: str) -> None:
    """A bound launch's arguments are the convenience path's: the same view geometry for a TMA operand, the same data
    pointer and dtype (and a contiguous tensor) for a pointer argument, the same values otherwise."""
    kinds = [
        kind for kind, _ in cake_jit.arg_plan_of(cake_backend.MODULES[module_name])
    ]
    assert len(got) == len(want) == len(kinds)
    for i, (g, w, kind) in enumerate(zip(got, want, kinds, strict=True)):
        if isinstance(w, torch.Tensor):
            assert isinstance(g, torch.Tensor), i
            if kind == "buffer":
                assert (g.data_ptr(), g.dtype) == (w.data_ptr(), w.dtype), i
                assert g.is_contiguous(), i
            else:
                assert (tuple(g.shape), g.stride(), g.data_ptr(), g.dtype) == (
                    tuple(w.shape),
                    w.stride(),
                    w.data_ptr(),
                    w.dtype,
                ), i
        else:
            assert type(g) is type(w) and g == w, (i, g, w)


def test_k1_entry_points_launch_the_bound_launch_of_their_key(monkeypatch):
    """Once a key is bound, the K1 entry points launch it straight from the key: no planning and no convenience call,
    the arguments of the convenience path's launch of the same call (fresh tensors of the key's geometry rebound), the
    stream context of a (thread, device, stream) made once.  The arena's workspace is converted again after a growth;
    tensors that alias keep their key unbound (the convenience path); ``cake_dense_gemm_det_train_convenience_cache_clear`` drops the bindings,
    their arena references and the stream contexts."""
    calls, made = _cpu_k1_entry_points(monkeypatch)
    bf16, T = torch.bfloat16, 1000
    X, W, G = (
        torch.randn(T, 4096).to(bf16),
        torch.randn(128, 4096).to(bf16),
        torch.randn(T, 128).to(bf16),
    )
    out_f, out_d, out_w = (
        torch.empty(T, 128, dtype=bf16),
        torch.empty(T, 4096, dtype=bf16),
        torch.empty(128, 4096),
    )

    def run():
        assert (
            cake_backend.cake_dense_gemm_det_train_projection_forward(X, W, out_f)
            is out_f
        )
        assert (
            cake_backend.cake_dense_gemm_det_train_projection_dgrad(G, W, out_d)
            is out_d
        )
        assert (
            cake_backend.cake_dense_gemm_det_train_projection_wgrad(G, X, out_w)
            is out_w
        )
        assert (
            cake_backend.cake_dense_gemm_det_train_projection(X, W.t(), out_f) is out_f
        )

    def same_calls(got, want):
        assert len(got) == len(want)
        for (name, args), (want_name, want_args) in zip(got, want, strict=True):
            assert name == want_name
            _same_launch_arguments(args, want_args, name)

    # the convenience path (no device index for the entry points' binding) plans every call; the second run's
    # launches (the arena at its grown size) are the reference
    monkeypatch.setattr(cake_backend, "_entry_index", lambda sources: -1)
    run()
    calls.clear()
    run()
    want = list(calls)
    assert len(want) == 4 and len(cake_backend._K1_CACHE) == 3
    assert not cake_backend._K1_BOUND_CACHE
    # the first call of each key binds the cached planned launch, then launches it
    monkeypatch.setattr(cake_backend, "_entry_index", lambda sources: 0)
    calls.clear()
    made.clear()
    run()
    same_calls(calls, want)
    assert len(cake_backend._K1_CACHE) == 3
    bound = list(cake_backend._K1_BOUND_CACHE.values())
    assert len(bound) == 4 and all(type(b) is cake_backend._BoundGemm for b in bound)
    (arena,) = cake_backend._ARENAS.values()
    assert arena.refs == 3 + 4  # the cached entries and the bindings
    assert all(b.state[0] == arena.version for b in bound)

    # a bound key goes from the key to the launch: no planning, no convenience call
    def planning(*args, **kwargs):
        raise AssertionError("planning path")

    monkeypatch.setattr(cake_backend, "_cached_gemm", planning)
    monkeypatch.setattr(cake_backend, "_launch_cached_gemm", planning)
    calls.clear()
    run()
    same_calls(calls, want)
    assert len(made) == 1
    # fresh tensors of the key's geometry are rebound
    other = torch.empty_like(out_f)
    assert (
        cake_backend.cake_dense_gemm_det_train_projection_forward(X, W, other) is other
    )
    pointers = {a.data_ptr() for a in calls[-1][1] if isinstance(a, torch.Tensor)}
    assert other.data_ptr() in pointers and out_f.data_ptr() not in pointers
    # a growth of the arena: the bound launches convert its workspace again
    kinds = {kind for b in bound for _, kind in b.workspace}
    assert kinds
    with cake_backend._PLAN_LOCK:
        for kind in kinds:
            arena.require(kind, arena.buffers[kind].numel() + 4096)
    assert all(b.state == (-1, None) for b in bound)
    calls.clear()
    run()
    for b, (_, args) in zip(bound, calls, strict=True):
        assert b.state[0] == arena.version
        assert all(args[i] is arena.buffers[kind] for i, kind in b.workspace)
    # another thread makes its own stream context of the same (device, stream)
    worker = threading.Thread(target=run)
    worker.start()
    worker.join()
    assert len(made) == 2 and made[0][0] != made[1][0] and made[0][1:] == made[1][1:]
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
    assert not cake_backend._K1_BOUND_CACHE and not cake_backend._STREAM_CONTEXTS
    assert cake_backend._ARENAS == {} and not cake_backend._K1_CACHE
    # tensors that alias (``W`` starts at ``X``): the key stays unbound and the convenience path launches
    monkeypatch.undo()
    calls, made = _cpu_k1_entry_points(monkeypatch)
    monkeypatch.setattr(cake_backend, "_entry_index", lambda sources: 0)
    assert (
        cake_backend.cake_dense_gemm_det_train_projection_forward(X, X[:128], out_f)
        is out_f
    )
    assert list(cake_backend._K1_BOUND_CACHE.values()) == [False, False]
    assert len(calls) == 1
    # the key does not record aliasing: a call of that geometry takes the convenience path as well
    assert (
        cake_backend.cake_dense_gemm_det_train_projection_forward(X, W, out_f) is out_f
    )
    assert len(cake_backend._K1_BOUND_CACHE) == 2 and len(calls) == 2
    (arena,) = cake_backend._ARENAS.values()
    assert arena.refs == 1  # the cached entry; an unbound key holds no reference


# GPU_ROWS cases the bound-launch test runs: a forward, an input gradient, an fp32 weight gradient and a swapped
# stream-K weight gradient.
_BOUND_ROWS = (
    ("kv_a", "fwd", "bf16", 257),
    ("kv_a", "dgrad", "bf16", 1001),
    ("kv_a", "wgrad", "f32", 257),
    ("indexer_hw", "wgrad", "bf16", 1001),
)


def test_k1_entry_points_bound_launch_is_bit_exact(record_property):
    """On the device the convenience path's launch of each row is judged against the naive BF16 tier over 32 draws,
    and on the last draw's operands the K1 entry points' bound launches give the bits of the convenience path's
    launch of the same call, each into NaN: on the first call of a key, on fresh outputs of a bound key (no
    allocation) and after a growth of the arena (the workspace converted again); the slice counters are zero after
    the launches."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    device = torch.device("cuda")
    arch = arch_for(device)
    names = [f"{row}_{op}_{out_dtype}" for row, op, out_dtype, _T in _BOUND_ROWS]

    def draw(seed):
        return [
            (op, _make_inputs("proj", row, op, out_dtype, T, seed=seed + i))
            for i, (row, op, out_dtype, T) in enumerate(_BOUND_ROWS)
        ]

    for _op, v in draw(SEED + 61):
        _require_program(_device_template(v))

    def convenience(op, v):
        out = torch.full_like(v["out"], float("nan"))
        if op != "wgrad":
            return cake_backend._launch_cached_gemm(v["A"], v["B"], out)
        A, B, t = cake_backend.wgrad_views(
            v["G"], v["X"], arch=arch, out_f32=out.dtype == torch.float32
        )
        return cake_backend._launch_cached_gemm(
            A, B, out, transposed_out=t, sk="auto", cta_rows=None
        )

    def entry(op, v, out):
        if op == "fwd":
            return cake_backend.cake_dense_gemm_det_train_projection_forward(
                v["X"], v["W"], out
            )
        if op == "dgrad":
            return cake_backend.cake_dense_gemm_det_train_projection_dgrad(
                v["G"], v["W"], out
            )
        return cake_backend.cake_dense_gemm_det_train_projection_wgrad(
            v["G"], v["X"], out
        )

    want = []

    def launch(cases):
        want[:] = [convenience(op, v) for op, v in cases]
        torch.cuda.synchronize()
        return {
            name: _d2_output(v, w)
            for name, (_op, v), w in zip(names, cases, want, strict=True)
        }

    def product(cases, dtype):
        return {
            name: _d2_product(v, dtype)["out"]
            for name, (_op, v) in zip(names, cases, strict=True)
        }

    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
    cases = judge_gemm(
        record_property, seed=SEED + 61, draw=draw, launch=launch, product=product
    )
    got = [entry(op, v, torch.full_like(v["out"], float("nan"))) for op, v in cases]
    torch.cuda.synchronize()
    assert all(torch.equal(a, b) for a, b in zip(got, want, strict=True))
    entries = list(cake_backend._K1_BOUND_CACHE.values())
    assert len(entries) == 4 and all(
        type(b) is cake_backend._BoundGemm for b in entries
    )
    # fresh outputs of the bound keys: no allocation, the same bits
    fresh = [torch.full_like(w, float("nan")) for w in want]
    torch.cuda.synchronize()
    before = torch.cuda.memory_stats()
    for (op, v), out in zip(cases, fresh, strict=True):
        entry(op, v, out)
    torch.cuda.synchronize()
    after = torch.cuda.memory_stats()
    assert after["allocation.all.allocated"] == before["allocation.all.allocated"]
    assert all(torch.equal(a, b) for a, b in zip(fresh, want, strict=True))
    # a growth of the arena: the bound launches convert its workspace again and keep the bits
    (arena,) = cake_backend._ARENAS.values()
    with cake_backend._PLAN_LOCK:
        for kind in ("k1_ws", "k1_counters"):
            arena.require(kind, arena.buffers[kind].numel() + 4096)
    for (op, v), out in zip(cases, fresh, strict=True):
        out.fill_(float("nan"))
        entry(op, v, out)
    torch.cuda.synchronize()
    assert all(b.state[0] == arena.version for b in entries)
    assert all(torch.equal(a, b) for a, b in zip(fresh, want, strict=True))
    counters = arena.buffers["k1_counters"].view(torch.int32)
    assert int(torch.count_nonzero(counters)) == 0
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
    assert not cake_backend._K1_BOUND_CACHE and cake_backend._ARENAS == {}


def test_convenience_path_memory_is_bounded_across_token_counts():
    """A ragged token count (a new T every step) must not grow the memory the convenience path holds: the
    router entries of 23 distinct T share one arena per (device, stream), so the memory held after the loop is
    about the single-T high-water mark (each entry used to own ~200 MiB of workspace: 4.16 GiB after 23 T),
    and a cached replay still matches the prepared path bit for bit."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    for a_mn, b_mn, out_t in (
        (False, False, False),
        (False, True, False),
        (True, True, True),
    ):
        _require_program(
            cake_backend.router_symbol(a_mn, b_mn, out_t)
        )  # kk / kn / nn_t
    device = torch.device("cuda")
    g = torch.Generator(device=device).manual_seed(SEED + 12)
    W = torch.randn(256, 6144, device=device, generator=g)

    def held_after(T_values):
        cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
        gc.collect()  # device tensors that only cyclic garbage of earlier tests still holds are not held here
        torch.cuda.synchronize()
        torch.cuda.empty_cache()
        base = torch.cuda.memory_allocated()
        for T in T_values:
            X = torch.randn(T, 6144, device=device, generator=g)
            G = torch.randn(T, 256, device=device, generator=g)
            cake_backend.cake_dense_gemm_det_train_router_forward(X, W)
            cake_backend.cake_dense_gemm_det_train_router_dgrad(G, W)
            cake_backend.cake_dense_gemm_det_train_router_wgrad(G, X)
        del X, G
        torch.cuda.synchronize()
        torch.cuda.empty_cache()
        return torch.cuda.memory_allocated() - base

    single = held_after([16022])
    assert len(cake_backend._K2_CACHE) == 3 and len(cake_backend._ARENAS) == 1
    (arena,) = cake_backend._ARENAS.values()
    assert arena.refs == 3 and single >= arena.nbytes() > 0
    loop = held_after(range(16000, 16023))
    assert len(cake_backend._K2_CACHE) == min(3 * 23, CONVENIENCE_CACHE_SIZE)
    assert loop <= 1.5 * single, (loop, single)
    assert loop < 2**30, loop  # far below the 4.16 GiB the per-entry workspaces held
    (arena,) = cake_backend._ARENAS.values()
    assert arena.refs == len(cake_backend._K2_CACHE)
    # the cached replay of the last T is allocation-free (``out`` given) and matches the prepared path
    T = 16022
    X = torch.randn(T, 6144, device=device, generator=g)
    G = torch.randn(T, 256, device=device, generator=g)
    outs = [torch.empty(T, 256, device=device) for _ in range(3)]
    nan_fill(outs)  # the replay and the prepared launch write into NaN
    cake_backend.cake_dense_gemm_det_train_router_forward(X, W, outs[0])
    torch.cuda.synchronize()
    before = torch.cuda.memory_stats()
    cake_backend.cake_dense_gemm_det_train_router_forward(X, W, outs[1])
    torch.cuda.synchronize()
    after = torch.cuda.memory_stats()
    assert after["allocation.all.allocated"] == before["allocation.all.allocated"]
    prepared = cake_dense_gemm_det_train_router_prepare(X, W.t(), outs[2], splits=4)
    prepared.launch()
    torch.cuda.synchronize()
    assert torch.equal(outs[0], outs[1]) and torch.equal(outs[0], outs[2])
    dw = cake_backend.cake_dense_gemm_det_train_router_wgrad(G, X)
    prepared_w = cake_dense_gemm_det_train_router_prepare(
        G.t(), X, torch.full_like(dw, float("nan")), splits=6
    )
    assert torch.equal(dw, prepared_w.launch())
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
    assert cake_backend._ARENAS == {}


# longer than a cold-cache JIT build; the hang this test guards against never returns
@pytest.mark.timeout(300)
def test_pd2_stream_k_on_an_odd_k_completes(record_property):
    """The dgrad of T = 1024, N = 1032, K = 1000 is one partial wave of 16 tiles of 17 K steps.  Two units per tile
    would leave the last one without a K step, and the pd 2 program waits for that unit's accumulator forever; the
    planner plans the 31 units that hold one.  The launch completes, and its output is judged against the naive
    BF16 tier over 32 draws written into the bound tensors."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    device = torch.device("cuda")
    g = torch.Generator(device=device).manual_seed(SEED + 11)
    T, N, K = 1024, 1032, 1000
    G = torch.randn(T, N, device=device, generator=g).to(torch.bfloat16)
    W = (torch.randn(N, K, device=device, generator=g) * N**-0.5).to(torch.bfloat16)
    v = dict(
        A=G,
        B=W,
        out=torch.full((T, K), float("nan"), device=device, dtype=torch.bfloat16),
    )
    knobs = _registered_knobs(
        v,
        dict(pd=2, slots=2, epi="tma"),
        dict(pd=2, slots=2, epi="tma", pro=15),
        dict(pd=2, slots=1, epi="tma", pro=15),
    )
    prepared = cake_dense_gemm_det_train_projection_prepare(
        v["A"], v["B"], v["out"], **knobs
    )
    plan = prepared.plan
    assert plan.pd == 2 and plan.k_blocks == 17 and plan.tail_tiles * 2 <= plan.sm_pairs
    assert (
        (plan.sk_units - 1) * plan.iters_per_unit
        < plan.sk_iters
        < 2 * plan.tail_tiles * plan.iters_per_unit
    )

    def draw(seed):
        gen = torch.Generator(device=device).manual_seed(seed)
        G.copy_(torch.randn(T, N, device=device, generator=gen).to(torch.bfloat16))
        W.copy_(
            (torch.randn(N, K, device=device, generator=gen) * N**-0.5).to(
                torch.bfloat16
            )
        )
        nan_fill([v["out"]])
        return G, W

    def launch(_):
        prepared.launch()
        torch.cuda.synchronize()
        return {"out": v["out"]}

    def product(operands, dtype):
        grad, w = (t.to(dtype) for t in operands)
        return {"out": torch.matmul(grad, w)}

    judge_gemm(
        record_property, seed=SEED + 11, draw=draw, launch=launch, product=product
    )


def _router_inputs(op, T, seed, K=6144, N=256, device="cuda"):
    g = torch.Generator(device=device).manual_seed(seed)
    X = torch.randn(T, K, device=device, generator=g)
    W = torch.randn(N, K, device=device, generator=g) * 0.02
    G = torch.randn(T, N, device=device, generator=g) * 1e-3
    if op == "fwd":
        return dict(A=X, B=W.t(), out=torch.empty(T, N, device=device), X=X, W=W, G=G)
    if op == "dgrad":
        return dict(A=G, B=W, out=torch.empty(T, K, device=device), X=X, W=W, G=G)
    return dict(A=G.t(), B=X, out=torch.empty(N, K, device=device), X=X, W=W, G=G)


def _d3_router_draw(op, T, v):
    """The judge's ``draw`` of a router binding ``v`` of :func:`_router_inputs`: the operands of the draw's seed written
    in place into ``v["X"]``, ``v["W"]`` and ``v["G"]`` (the views ``v["A"]`` and ``v["B"]`` a prepared launch is
    bound to follow them)."""

    def draw(seed):
        fresh = _router_inputs(op, T, seed=seed)
        for name in ("X", "W", "G"):
            v[name].copy_(fresh[name])
        return v

    return draw


@pytest.mark.parametrize(
    "op, T", [("fwd", 257), ("dgrad", 257), ("wgrad", 1001), ("fwd", 129)]
)
def test_router_rows_match_fp64_reference_and_rerun_bit_exact(op, T, record_property):
    """The router's prepared launch of the default split count, judged against the naive BF16 tier over 32 draws.
    On the last draw a rerun into a NaN-poisoned ``out`` allocates nothing and gives the same bits; the eager entry
    point of the row gives the same bits too, and its second call hits the cached plan and allocates only ``out``."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    v = _router_inputs(op, T, seed=SEED + 4)
    plan, *_ = cake_dense_gemm_det_train_router_plan(v["A"], v["B"], v["out"])
    _require_program(plan.template)
    prepared = cake_dense_gemm_det_train_router_prepare(v["A"], v["B"], v["out"])
    assert prepared.splits == ROUTER_SPLITS[plan.layout]

    def launch(v):
        nan_fill([v["out"]])
        prepared.launch()
        torch.cuda.synchronize()
        return {"out": v["out"]}

    def product(v, dtype):
        return {"out": torch.matmul(v["A"].to(dtype), v["B"].to(dtype))}

    judge_gemm(
        record_property,
        seed=SEED + 4,
        draw=_d3_router_draw(op, T, v),
        launch=launch,
        product=product,
    )
    first = v["out"].clone()
    nan_fill([v["out"]])
    torch.cuda.synchronize()
    before = torch.cuda.memory_stats()
    prepared.launch()  # bit-exact rerun, no allocation (the split, the launch and the reduction included)
    torch.cuda.synchronize()
    after = torch.cuda.memory_stats()
    assert after["allocation.all.allocated"] == before["allocation.all.allocated"]
    assert torch.equal(first, v["out"])
    # the eager entry point of the row gives the same bits
    eager_fn = dict(
        fwd=lambda: cake_backend.cake_dense_gemm_det_train_router_forward(
            v["X"], v["W"]
        ),
        dgrad=lambda: cake_backend.cake_dense_gemm_det_train_router_dgrad(
            v["G"], v["W"]
        ),
        wgrad=lambda: cake_backend.cake_dense_gemm_det_train_router_wgrad(
            v["G"], v["X"]
        ),
    )[op]
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
    eager = eager_fn()
    torch.cuda.synchronize()
    assert torch.equal(eager, v["out"])
    assert len(cake_backend._K2_CACHE) == 1
    # the second eager call hits the cached plan: only ``out`` is allocated, the same bits come back
    before = torch.cuda.memory_stats()
    again = eager_fn()
    torch.cuda.synchronize()
    after = torch.cuda.memory_stats()
    assert after["allocation.all.allocated"] - before["allocation.all.allocated"] == 1
    assert len(cake_backend._K2_CACHE) == 1 and torch.equal(again, v["out"])


@pytest.mark.parametrize("op, T", [("fwd", 257), ("dgrad", 257), ("wgrad", 1001)])
def test_router_misaligned_out_is_refused_or_matches_fp64_reference(
    op, T, record_property
):
    """An ``out`` 4 bytes past a 16-byte boundary on the device: a single-split ``kk`` / ``kn`` launch is refused
    on both host paths before anything is launched (its 16-byte vector store would fault with a misaligned
    address); the split-K launches and the transposed ``nn_t`` store write the bits of an aligned ``out``.  The
    aligned ``out`` of each split count is judged against the naive BF16 tier over 32 draws."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    v = _router_inputs(op, T, seed=SEED + 22)
    plan, *_ = cake_dense_gemm_det_train_router_plan(v["A"], v["B"], v["out"])
    _require_program(plan.template)
    rows, cols = (int(s) for s in v["out"].shape)
    counts = sorted({1, 2, ROUTER_SPLITS[plan.layout]})
    if not plan.transposed_out:
        shifted = _offset_out(rows, cols, 1, device="cuda")
        eager = _offset_out(rows, cols, 1, device="cuda")
        cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
        with pytest.raises(ValueError, match="16-byte aligned address"):
            cake_dense_gemm_det_train_router_prepare(v["A"], v["B"], shifted, splits=1)
        with pytest.raises(ValueError, match="16-byte aligned address"):
            cake_backend.cake_dense_gemm_det_train_router(
                v["A"], v["B"], eager, splits=1
            )
        torch.cuda.synchronize()  # nothing was launched: the context stays healthy
    aligned = {splits: _offset_out(rows, cols, 0, device="cuda") for splits in counts}
    prepared = {
        splits: cake_dense_gemm_det_train_router_prepare(
            v["A"], v["B"], aligned[splits], splits=splits
        )
        for splits in counts
    }

    def launch(v):
        nan_fill(aligned.values())
        for splits in counts:
            prepared[splits].launch()
        torch.cuda.synchronize()
        return {f"out_splits_{splits}": aligned[splits] for splits in counts}

    def product(v, dtype):
        expected = torch.matmul(v["A"].to(dtype), v["B"].to(dtype))
        return {f"out_splits_{splits}": expected for splits in counts}

    judge_gemm(
        record_property,
        seed=SEED + 22,
        draw=_d3_router_draw(op, T, v),
        launch=launch,
        product=product,
    )
    # on the last draw: the shifted ``out`` of each split count the host paths take holds the aligned bits
    for splits in counts:
        if splits == 1 and not plan.transposed_out:
            continue
        shifted = _offset_out(rows, cols, 1, device="cuda")
        eager = _offset_out(rows, cols, 1, device="cuda")
        nan_fill([shifted, eager])
        cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
        cake_dense_gemm_det_train_router_prepare(
            v["A"], v["B"], shifted, splits=splits
        ).launch()
        cake_backend.cake_dense_gemm_det_train_router(
            v["A"], v["B"], eager, splits=splits
        )
        torch.cuda.synchronize()
        for out in (shifted, eager):
            assert torch.equal(out, aligned[splits]), splits


def test_fused_split_matches_the_torch_chain_bit_exactly():
    """The fused split program writes the bits of the torch chain for W [256, 6144], a ragged element count
    and contiguous sources at 4-, 8- and 16-byte storage offsets; the K2 paths bind it and allocate no fp32
    scratch.  Runs only where this checkout registers the program for the device."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    device = torch.device("cuda")
    arch = cake_backend.arch_for(device)
    module = cake_backend.fused_split_module(arch)
    if module is None:
        pytest.skip(
            f"fused split program {cake_backend.SPLIT_TEMPLATE!r} not registered for {arch}"
        )
    g = torch.Generator(device=device).manual_seed(SEED + 21)
    W = torch.randn(256, 6144, device=device, generator=g) * torch.logspace(
        -3, 3, 6144, device=device
    )
    ragged = torch.randn(
        7, 1001, device=device, generator=g
    )  # 7007: no multiple of 8 or of a block
    base = torch.randn(3 * 1001 + 8, device=device, generator=g)
    sources = [W, ragged] + [base[k : k + 3 * 1001].view(3, 1001) for k in (1, 2, 4)]
    index = cake_backend._device_index(device)
    for src in sources:
        n = src.numel()
        fused = torch.empty((3, *src.shape), device=device, dtype=torch.bfloat16)
        chain = torch.empty_like(fused)
        split_fp32_to_bf16x3_det_(src, chain, torch.empty_like(src))
        launch = bind_launch(
            module,
            cake_backend._split_values(src, fused, n),
            cake_backend._split_grid(n),
            arch,
        )
        with cake_backend._ffi_stream_context(index):
            launch()
        torch.cuda.synchronize()
        assert torch.equal(fused.view(torch.int16), chain.view(torch.int16)), tuple(
            src.shape
        )
    # the K2 paths take the program: no fp32 scratch is allocated (prepared) or carved (convenience) and the
    # two paths agree bit for bit
    _require_program("router_fp32_det_gemm_kk")
    X = torch.randn(257, 6144, device=device, generator=g)
    prepared = cake_dense_gemm_det_train_router_prepare(
        X, W.t(), torch.empty(257, 256, device=device), splits=4
    )
    assert prepared.fused_split and "resid" not in prepared.tensors
    first = prepared.launch().clone()
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
    eager = cake_backend.cake_dense_gemm_det_train_router_forward(X, W)
    cached = next(iter(cake_backend._K2_CACHE.values()))
    assert cached.split is not None and "k2_resid" not in cached.arena.buffers
    assert "resid" not in cake_backend._entry_views(cached)
    torch.cuda.synchronize()
    assert torch.equal(first, eager)
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()


def test_sm107a_n128_wgrad_rules_plan():
    # six sm_107a keys for the swapped N = 128 weight gradients of the 4096 / 5120 / 8192 rows (bf16 and fp32 out), measured on
    # R200 against the ruleless plan: 128 x 128 pair tiles (cta_rows 64) with the exact three-way (4096) / two-way (5120) K
    # split of the tail tiles, and 256 x 128 pair tiles with the synchronised stream-K tail (8192); the 6144 row (indexer_k)
    # keeps its 64-row family rule
    want_rule = {
        4096: {"block_n": 128, "cta_rows": 64, "sk_exact": 3, "pro": 15},
        5120: {"block_n": 128, "cta_rows": 64, "sk_exact": 2, "pro": 15},
        8192: {"block_n": 128, "sk_sync": True},
    }
    # (template, tail_tiles, sk_units, iters_per_unit) of the bf16 row at T 16231 on 212 SMs; the fp32 row takes the _f32 program
    want_plan = {
        4096: ("dense_proj_det_gemm_nn_n128_m64_hen_t_skx_pro15", 32, 96, 85),
        5120: ("dense_proj_det_gemm_nn_n128_m64_hen_t_skx_pro15", 40, 80, 127),
        8192: ("dense_proj_det_gemm_nn_n128_hen_t_sks_pro7", 32, 64, 127),
    }
    T = 16231
    for K, rule in want_rule.items():
        for f32 in (False, True):
            assert (
                ROW_RULES[("sm_107a", True, True, f32, True, False, 128, None, K)]
                == rule
            )
            G = torch.empty(T, 128, dtype=torch.bfloat16)
            X = torch.empty(T, K, dtype=torch.bfloat16)
            out = torch.empty(128, K, dtype=torch.float32 if f32 else torch.bfloat16)
            A, B, transposed = wgrad_views(G, X, arch="sm_107a", out_f32=f32)
            assert transposed
            plan = cake_dense_gemm_det_train_projection_plan(
                A,
                B,
                out,
                sm_count=212,
                l2_bytes=L2_BYTES,
                transposed_out=transposed,
                arch="sm_107a",
                _fallback=False,
            )[0]
            template, tail, units, ipu = want_plan[K]
            if f32:
                template = template.replace("_hen_t", "_hen_f32_t")
            assert (
                plan.template,
                plan.tail_tiles,
                plan.sk_units,
                plan.iters_per_unit,
            ) == (template, tail, units, ipu), (K, f32)


# The sm_107a T-exact weight-gradient key of the 4096 -> 1024 fp32 weight gradient at T 16384 (K = T, the direct
# orientation): the rule of its T 16231 key, with the per-tile K partitions of the row's plan without it.
SM107A_T16384_WGRAD_KEY = ("sm_107a", True, True, True, False, False, 4096, 16384, 1024)


def _k_partitions(plan):
    """The distinct per-tile K-step partitions of a plan (where every output element's K sum is split)."""
    kb = int(plan.k_blocks)
    if not plan.sk_units or plan.htail_plan:
        return [(0, kb)]
    parts = {(0, kb)} if plan.num_full else set()
    if plan.sk_exact:
        step = -(-kb // int(plan.sk_exact))
        parts.add(tuple(sorted(set(range(0, kb, step)) | {kb})))
    elif plan.sk_sync:
        parts.add((0, int(plan.iters_per_unit), kb))
    else:
        ipu, units = int(plan.iters_per_unit), int(plan.sk_units)
        for t in range(int(plan.tail_tiles)):
            lo, hi = t * kb, (t + 1) * kb
            cuts = {lo, hi} | {u * ipu for u in range(units + 1) if lo < u * ipu < hi}
            parts.add(tuple(x - lo for x in sorted(cuts)))
    return sorted(parts)


def _sm107a_wgrad_plan(N, T, M, sm_count):
    G = torch.empty(T, M, dtype=torch.bfloat16)
    X = torch.empty(T, N, dtype=torch.bfloat16)
    out = torch.empty(M, N, dtype=torch.float32)
    A, B, transposed = wgrad_views(G, X, arch="sm_107a", out_f32=True)
    assert not transposed, (N, T, M)
    plan, *_ = cake_dense_gemm_det_train_projection_plan(
        A,
        B,
        out,
        sm_count=sm_count,
        l2_bytes=L2_BYTES,
        arch="sm_107a",
    )
    return plan


def test_sm107a_t16384_wgrad_key_plans_the_t16231_rule(monkeypatch):
    """The sm_107a 4096 -> 1024 fp32 weight-gradient key at T 16384 carries the rule of the row's T 16231 key and plans
    its program on every sm_107a SM count without a registry fallback, with the per-tile K partitions of the row's plan
    without the key (the launcher's plan: the registry fallback of the default tile to the 256-row tall tile);
    one token more or less plans that plan."""
    monkeypatch.setattr(cake_backend, "_DUMMIES", {})
    key = SM107A_T16384_WGRAD_KEY
    # the row's ragged key carries the same rule at every other token count: compare with the row before either key
    monkeypatch.delitem(ROW_RULES, key[:7] + (None,) + key[8:])
    _arch, _a_mn, _b_mn, _f32, _out_t, _batched, N, T, M = key
    sibling = key[:7] + (16231,) + key[8:]
    assert ROW_RULES[key] == ROW_RULES[sibling]
    registered = _registered("sm_107a")
    for sm_count in (208, 212, 216):
        plans = {t: _sm107a_wgrad_plan(N, t, M, sm_count) for t in (T - 1, T, T + 1)}
        sib = _sm107a_wgrad_plan(N, 16231, M, sm_count)
        with monkeypatch.context() as m:
            m.delitem(ROW_RULES, key)
            without = {
                t: _sm107a_wgrad_plan(N, t, M, sm_count) for t in (T - 1, T, T + 1)
            }
        for t in (T - 1, T + 1):
            assert _plan_signature(plans[t]) == _plan_signature(without[t]), (
                sm_count,
                t,
            )
        plan, plain = plans[T], without[T]
        assert plan.template == sib.template and plan.template in registered, (
            sm_count,
            plan.template,
        )
        assert not (plan.rule_fallback or plan.knob_fallback or plan.swap_fallback)
        assert plan.template != plain.template, (sm_count, plain.template)
        assert (plan.block_n, plan.cta_rows, plan.b_swz) == (160, 256, 64)
        assert _k_partitions(plan) == _k_partitions(plain), (sm_count, plain.template)


