# ---------------------------------------------------------------------------
# The swapped small-token forward (``swap_ab_<tile>`` programs)
# ---------------------------------------------------------------------------

SWAP_TEMPLATES = dict((t, w) for w, t in cake_backend.SWAP_TEMPLATES)


def test_swap_ab_template_fills_one_wave_with_the_narrow_tile():
    """The narrow weight tile while its CTAs fit one wave of the device's SMs, the wide one up to two waves, the
    planner's program beyond; ``None`` on an architecture that registers neither."""
    pick = cake_backend.swap_ab_template
    for arch in cake_jit.ARCHES:
        # the grouped wo_a rows: 8 groups x 1024 weight rows, 64-token tiles
        assert pick(8, 64, 1024, 152, arch) == "swap_ab_w64_t64_s12"  # 128 CTAs
        assert pick(8, 65, 1024, 152, arch) == "swap_ab_w128_t64_s8"  # 256 > 152
        assert pick(8, 128, 1024, 256, arch) == "swap_ab_w64_t64_s12"  # 256 <= 256
        assert pick(8, 256, 1024, 152, arch) == "swap_ab_w128_t64_s8"  # 256 <= 2 waves
        # past two waves of the wide tile the planner's program runs
        assert pick(8, 64, 4096, 152, arch) == "swap_ab_w128_t64_s8"  # 256 CTAs
        assert pick(8, 128, 4096, 152, arch) is None  # 512 CTAs
        assert pick(8, 128, 4096, 256, arch) == "swap_ab_w128_t64_s8"  # 512 <= 2 x 256
    assert pick(8, 64, 1024, 152, "sm_90a") is None


def _swap_views(T, G=8, D=4096, R=1024, seed=SEED, token_major=True):
    """The grouped projection views ``A [G, T, D]``, ``B [G, D, R]`` (K-major weights) and ``out [G, T, R]``:
    token-major ``[T, G, *]`` storage permuted (SGLang's ``o`` and ``result``), or contiguous ``[G, T, *]``."""
    g = torch.Generator(device="cuda").manual_seed(seed)
    w = (torch.randn(G, R, D, device="cuda", generator=g) * D**-0.5).to(torch.bfloat16)
    if token_major:
        o = torch.randn(T, G, D, device="cuda", generator=g).to(torch.bfloat16)
        res = torch.full((T, G, R), float("nan"), device="cuda", dtype=torch.bfloat16)
        return o.transpose(0, 1), w.transpose(1, 2), res.transpose(0, 1)
    o = torch.randn(G, T, D, device="cuda", generator=g).to(torch.bfloat16)
    res = torch.full((G, T, R), float("nan"), device="cuda", dtype=torch.bfloat16)
    return o, w.transpose(1, 2), res


def _require_swap():
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    for template in SWAP_TEMPLATES:
        _require_program(template)


def _swap_launch(A, B, out):
    return cake_backend._swap_ab_cached(A, B, out, False)


def _swap_expected(A, B):
    """The template :func:`swap_ab_template` picks for these views on this device."""
    L, M, _ = A.shape
    facts = cake_backend.device_facts(A.device)
    return cake_backend.swap_ab_template(L, M, B.shape[2], facts.sm_count, facts.arch)


def _d3_swap_forward(views):
    """The judge's ``launch`` of :func:`_swap_views` views ``(A, B, out)``: the convenience entry point into ``out``."""
    A, B, out = views
    cake_backend.cake_dense_gemm_det_train_projection(A, B, out)
    torch.cuda.synchronize()
    return {"out": out}


def _d3_swap_product(views, dtype):
    """The judge's ``product`` of :func:`_swap_views` views ``(A, B, out)``: the grouped ``A @ B`` in ``dtype``."""
    A, B, _out = views
    return {"out": torch.einsum("gtd,gdr->gtr", A.to(dtype), B.to(dtype))}


@pytest.mark.parametrize("token_major", [True, False])
@pytest.mark.parametrize("T", [1, 7, 16, 63, 64, 65, 100, 128, 192, 255, 256])
def test_swapped_forward_matches_fp64_on_the_grouped_views(
    T, token_major, record_property
):
    """Every batched forward row of at most 256 tokens runs a swapped program, in place on SGLang's token-major
    views or on contiguous ones; its output is judged against the naive BF16 tier over 32 draws."""
    _require_swap()
    A, B, out = _swap_views(T, token_major=token_major)
    launch, template = _swap_launch(A, B, out), _swap_expected(A, B)
    assert (
        template is not None
    )  # the grouped wo_a rows fit two waves of a Blackwell part
    assert cake_jit.MODULES[launch.module_name]["template"] == template
    judge_gemm(
        record_property,
        seed=SEED,
        draw=lambda s: _swap_views(T, token_major=token_major, seed=s),
        launch=_d3_swap_forward,
        product=_d3_swap_product,
    )


@pytest.mark.parametrize(
    "L, T, K, N", [(2, 33, 128, 512), (3, 100, 4160, 1032), (16, 8, 576, 256)]
)
def test_swapped_forward_other_shapes(L, T, K, N, record_property):
    """Other batches, K (a multiple of 64) and N (a multiple of 8, not of the weight tile): tails in both tiles,
    judged against the naive BF16 tier over 32 draws."""
    _require_swap()
    A, B, out = _swap_views(T, G=L, D=K, R=N, seed=SEED + 1)
    launch = _swap_launch(A, B, out)
    assert launch is not None
    assert cake_jit.MODULES[launch.module_name]["template"] == _swap_expected(A, B)
    judge_gemm(
        record_property,
        seed=SEED + 1,
        draw=lambda s: _swap_views(T, G=L, D=K, R=N, seed=s),
        launch=_d3_swap_forward,
        product=_d3_swap_product,
    )


def test_swapped_forward_declines_the_rows_it_does_not_take():
    """Rows the swapped programs do not serve stay on the planner: more than 256 tokens, more than two waves of
    tiles, one batch, an FP32 output, a transposed store, an MN-major weight view, a K that is not a multiple of
    64."""
    _require_swap()
    A, B, out = _swap_views(257)
    assert _swap_launch(A, B, out) is None
    wide = 128 * (2 * cake_backend.device_sm_count(A.device) // 8 + 1)
    A, B, out = _swap_views(64, G=8, D=1024, R=wide)
    assert (
        _swap_expected(A, B) is None and _swap_launch(A, B, out) is None
    )  # past two waves
    A, B, out = _swap_views(64, G=1)
    assert _swap_launch(A[0], B[0], out[0]) is None and _swap_launch(A, B, out) is None
    A, B, out = _swap_views(64)
    assert _swap_launch(A, B, out.float()) is None
    assert _swap_launch(A, B.contiguous(), out) is None  # B unit stride on n: MN-major
    A, B, out = _swap_views(64, D=4096 + 8)
    assert _swap_launch(A, B, out) is None
    assert cake_backend._swap_ab_launch(*_swap_views(64), True) is None


def test_swapped_forward_is_bitwise_repeatable():
    """One FP32 sum per output element, rounded once: reruns give the same bits."""
    _require_swap()
    for T in (64, 128):
        A, B, out = _swap_views(T, seed=SEED + 2)
        cake_backend.cake_dense_gemm_det_train_projection(A, B, out)
        first = out.clone()
        for _ in range(REPEATS):
            out.fill_(float("nan"))
            cake_backend.cake_dense_gemm_det_train_projection(
                A, B, out, enable_pdl=True
            )
            torch.cuda.synchronize()
            assert torch.equal(out, first)


@pytest.mark.parametrize("T", [16, 128])
def test_swapped_forward_pdl_waits_for_an_early_producer(T, record_property):
    """A chain of programmatic dependent launches whose producer triggers its dependents at entry: the first
    projection (K = 16384, long) writes the activation the second reads.  The second starts while the first runs
    (its weights load ahead of the wait) and must still read every token the first wrote: both outputs are judged
    against the naive BF16 tier over 32 draws, three chains on the first, the second on the activation the first
    wrote."""
    _require_swap()
    G, D1, R1, R2 = 8, 16384, 1024, 2048

    def draw(seed):
        g = torch.Generator(device="cuda").manual_seed(seed)
        x = torch.randn(T, G, D1, device="cuda", generator=g).to(torch.bfloat16)
        w1 = (torch.randn(G, R1, D1, device="cuda", generator=g) * D1**-0.5).to(
            torch.bfloat16
        )
        w2 = (torch.randn(G, R2, R1, device="cuda", generator=g) * R1**-0.5).to(
            torch.bfloat16
        )
        mid = torch.empty(T, G, R1, device="cuda", dtype=torch.bfloat16)
        y = torch.empty(T, G, R2, device="cuda", dtype=torch.bfloat16)
        return SimpleNamespace(
            mid=mid,
            y=y,
            A1=x.transpose(0, 1),
            B1=w1.transpose(1, 2),
            O1=mid.transpose(0, 1),
            A2=mid.transpose(0, 1),
            B2=w2.transpose(1, 2),
            O2=y.transpose(0, 1),
        )

    def launch(v):
        nan_fill([v.mid, v.y])
        assert _swap_launch(v.A1, v.B1, v.O1) is not None
        assert _swap_launch(v.A2, v.B2, v.O2) is not None
        cake_backend.cake_dense_gemm_det_train_projection(
            v.A1, v.B1, v.O1, enable_pdl=True
        )
        cake_backend.cake_dense_gemm_det_train_projection(
            v.A2, v.B2, v.O2, enable_pdl=True
        )
        torch.cuda.synchronize()
        assert bool(torch.isfinite(v.mid).all()) and bool(torch.isfinite(v.y).all())
        return {"mid": v.O1, "y": v.O2}

    def product(v, dtype):
        return {
            "mid": torch.einsum("gtd,gdr->gtr", v.A1.to(dtype), v.B1.to(dtype)),
            "y": torch.einsum("gtd,gdr->gtr", v.A2.to(dtype), v.B2.to(dtype)),
        }

    judge_gemm(
        record_property,
        seed=SEED + 3,
        draw=draw,
        launch=launch,
        product=product,
        launches=3,
        after_launch=True,
    )


@pytest.mark.parametrize("T", [16, 128])
def test_swapped_forward_default_waits_for_an_early_producer_writing_b(
    T, record_property
):
    """The default (``enable_pdl`` on, ``weights_static`` off) never reads ``B`` before the preceding kernel
    completes: a long planner GEMM on a few CTAs (K = 65536) that triggers its dependents at entry writes the weights
    the swapped forward reads next, and the forward sees every weight it wrote: both outputs are judged against the
    naive BF16 tier over 32 draws, three chains on the first, the forward on the weights the producer wrote.  (The
    ``weights_static`` programs read the NaN the weights were poisoned with in this chain: that is what the keyword
    states cannot happen.)"""
    _require_swap()
    G, D, R, Kp = 2, 256, 256, 65536

    def draw(seed):
        g = torch.Generator(device="cuda").manual_seed(seed)
        y = (torch.randn(G, R, Kp, device="cuda", generator=g) * Kp**-0.5).to(
            torch.bfloat16
        )
        z = torch.randn(G, D, Kp, device="cuda", generator=g).to(torch.bfloat16)
        o = torch.randn(T, G, D, device="cuda", generator=g).to(torch.bfloat16)
        w = torch.empty(G, R, D, device="cuda", dtype=torch.bfloat16)
        res = torch.empty(T, G, R, device="cuda", dtype=torch.bfloat16)
        return SimpleNamespace(
            y=y,
            z=z,
            w=w,
            res=res,
            A=o.transpose(0, 1),
            B=w.transpose(1, 2),
            O=res.transpose(0, 1),
        )

    def launch(v):
        swapped = _swap_launch(v.A, v.B, v.O)
        assert swapped is not None
        assert not cake_jit.MODULES[swapped.module_name]["template"].endswith("_we")
        nan_fill([v.w, v.res])
        # the producer of the weights: w[g] = y[g] @ z[g].T on the planner's program (N < 2 M: not swapped)
        cake_backend.cake_dense_gemm_det_train_projection(v.y, v.z.transpose(1, 2), v.w)
        cake_backend.cake_dense_gemm_det_train_projection(v.A, v.B, v.O)
        torch.cuda.synchronize()
        assert bool(torch.isfinite(v.w).all())
        return {"w": v.w, "out": v.O}

    def product(v, dtype):
        return {
            "w": torch.matmul(v.y.to(dtype), v.z.to(dtype).transpose(1, 2)),
            "out": torch.einsum("gtd,gdr->gtr", v.A.to(dtype), v.B.to(dtype)),
        }

    judge_gemm(
        record_property,
        seed=SEED + 8,
        draw=draw,
        launch=launch,
        product=product,
        launches=3,
        after_launch=True,
    )


def test_weights_static_runs_the_weights_early_program(record_property):
    """``weights_static=True`` with PDL routes the swapped rows to the ``_we`` programs.  On weights no kernel in
    flight writes, the default program's output and the ``_we`` program's output are each judged against the naive
    BF16 tier over 32 draws."""
    _require_swap()
    for template in cake_backend.SWAP_TEMPLATES_WEIGHTS_STATIC:
        _require_program(template[1])
    A, B, out = _swap_views(64, seed=SEED + 9)
    early = cake_backend._swap_ab_cached(A, B, out, False, True)
    assert early is not None
    assert cake_jit.MODULES[early.module_name]["template"].endswith("_we")

    def draw(seed):
        views = _swap_views(64, seed=seed)
        return (*views, torch.full_like(views[2], float("nan")))

    def launch(views):
        A, B, out, early_out = views
        cake_backend.cake_dense_gemm_det_train_projection(A, B, out)
        cake_backend.cake_dense_gemm_det_train_projection(
            A, B, early_out, weights_static=True
        )
        torch.cuda.synchronize()
        return {"out": out, "weights_static_out": early_out}

    def product(views, dtype):
        expected = _d3_swap_product(views[:3], dtype)["out"]
        return {"out": expected, "weights_static_out": expected}

    judge_gemm(
        record_property, seed=SEED + 9, draw=draw, launch=launch, product=product
    )


def test_swapped_forward_replays_in_a_cuda_graph_with_pdl(record_property):
    """The swapped launch allocates nothing: a PDL chain captured into a CUDA graph replays on new values written
    into the bound views.  Each draw writes its operands into the bound views and replays the graph; both outputs
    are judged against the naive BF16 tier over 32 draws, the second on the first's output as the replay wrote it."""
    _require_swap()
    A, B, out = _swap_views(96, seed=SEED + 4)
    _, B2, out2 = _swap_views(96, R=4096, D=1024, seed=SEED + 5)
    A2 = out  # the second projection reads the first's output

    def chain():
        cake_backend.cake_dense_gemm_det_train_projection(A, B, out, enable_pdl=True)
        cake_backend.cake_dense_gemm_det_train_projection(A2, B2, out2, enable_pdl=True)

    chain()
    torch.cuda.synchronize()
    stream = torch.cuda.Stream()
    stream.wait_stream(torch.cuda.current_stream())
    graph = torch.cuda.CUDAGraph()
    with torch.cuda.graph(graph, stream=stream):
        chain()

    def draw(seed):
        first = _swap_views(96, seed=seed)
        second = _swap_views(96, R=4096, D=1024, seed=seed + 1)
        A.copy_(first[0])
        B.copy_(first[1])
        B2.copy_(second[1])
        return A, B, B2, A2

    def launch(_operands):
        nan_fill([out, out2])
        graph.replay()
        torch.cuda.synchronize()
        return {"out": out, "out2": out2}

    def product(operands, dtype):
        a, b, b2, a2 = (t.to(dtype) for t in operands)
        return {
            "out": torch.einsum("gtd,gdr->gtr", a, b),
            "out2": torch.einsum("gtd,gdr->gtr", a2, b2),
        }

    judge_gemm(
        record_property,
        seed=SEED + 4,
        draw=draw,
        launch=launch,
        product=product,
        after_launch=True,
    )


# ---------------------------------------------------------------------------
# Programmatic dependent launch of the planner's programs
# ---------------------------------------------------------------------------


def test_every_program_takes_enable_pdl_per_call():
    """Every program (the planner's, the eight-warp form, the swapped forward, the router and its split kernel) takes
    the per-call PDL flag right before the grid."""
    for name, record in cake_jit.MODULES.items():
        plan = [list(item) for item in cake_jit.arg_plan_of(record)]
        assert plan[-4] == ["launch", "enable_pdl"], (name, plan[-4])
        assert sum(kind == "launch" for kind, _ in plan) == 1, name


def test_weights_static_selects_the_weights_early_programs():
    """Each swapped tile ships twice on every architecture: the default program, whose weight loads wait for the
    preceding kernel, and the ``_we`` one, whose weight loads run ahead of the wait; ``weights_static`` picks it."""
    for arch in cake_jit.ARCHES:
        for (w, safe), (w_we, early) in zip(
            cake_backend.SWAP_TEMPLATES,
            cake_backend.SWAP_TEMPLATES_WEIGHTS_STATIC,
            strict=True,
        ):
            assert w == w_we and early == f"{safe}_we"
            assert cake_jit.select_module(arch, safe) != cake_jit.select_module(
                arch, early
            )
        pick = cake_backend.swap_ab_template
        assert pick(8, 64, 1024, 152, arch) == "swap_ab_w64_t64_s12"
        assert pick(8, 64, 1024, 152, arch, True) == "swap_ab_w64_t64_s12_we"
        assert pick(8, 256, 1024, 152, arch, True) == "swap_ab_w128_t64_s8_we"


def test_enable_pdl_defaults_to_device_support():
    if not _device_supported():
        pytest.skip("requires a device with a registered generated instance")
    device = torch.device("cuda")
    assert cake_backend.pdl_enabled(None, device) is True
    assert cake_backend.pdl_enabled(False, device) is False
    assert cake_backend.pdl_enabled(True, device) is True


def _pdl_chain_inputs(T, D1, R1, R2, seed):
    g = torch.Generator(device="cuda").manual_seed(seed)
    x = torch.randn(T, D1, device="cuda", generator=g).to(torch.bfloat16)
    w1 = (torch.randn(R1, D1, device="cuda", generator=g) * D1**-0.5).to(torch.bfloat16)
    w2 = (torch.randn(R2, R1, device="cuda", generator=g) * R1**-0.5).to(torch.bfloat16)
    return x, w1, w2


def _d3_pdl_chain_product(v, dtype):
    """The judge's ``product`` (``after_launch``) of a PDL chain: ``mid = x @ w1.T`` on the operands ``v.x`` and
    ``v.w1``, and ``y = mid @ w2.T`` on the ``v.mid`` the first projection wrote and ``v.w2``, in ``dtype``."""
    return {
        "mid": v.x.to(dtype) @ v.w1.to(dtype).t(),
        "y": v.mid.to(dtype) @ v.w2.to(dtype).t(),
    }


@pytest.mark.parametrize("T", [256, 4096])
def test_planner_pdl_waits_for_an_early_producer(T, record_property):
    """A chain of programmatic dependent launches through the planner's programs: the first projection (K = 16384)
    triggers its dependent at entry and writes the activation the second reads.  The second starts while the first
    runs and must still read every row the first wrote, and at 256 rows both run stream-K out of one workspace arena
    (the slabs and slice counters of the stream), which the second may touch only after the first completes.  Both
    outputs are judged against the naive BF16 tier over 32 draws, three chains into NaN outputs on the first (the
    second on the activation the first wrote); on the last draw the default ``enable_pdl`` gives the bits of the
    explicit one."""
    if not _device_supported():
        pytest.skip("requires a device with a registered generated instance")

    def draw(seed):
        x, w1, w2 = _pdl_chain_inputs(T, 16384, 2048, 1024, seed)
        mid = torch.empty(T, 2048, device="cuda", dtype=torch.bfloat16)
        y = torch.empty(T, 1024, device="cuda", dtype=torch.bfloat16)
        return SimpleNamespace(x=x, w1=w1, w2=w2, mid=mid, y=y)

    def launch(v):
        nan_fill([v.mid, v.y])
        cake_backend.cake_dense_gemm_det_train_projection_forward(
            v.x, v.w1, v.mid, enable_pdl=True
        )
        cake_backend.cake_dense_gemm_det_train_projection_forward(
            v.mid, v.w2, v.y, enable_pdl=True
        )
        torch.cuda.synchronize()
        return {"mid": v.mid, "y": v.y}

    v = judge_gemm(
        record_property,
        seed=SEED + 6,
        draw=draw,
        launch=launch,
        product=_d3_pdl_chain_product,
        launches=3,
        after_launch=True,
    )
    # the default (the device supports PDL) gives the same bits
    first = v.y.clone()
    nan_fill([v.mid, v.y])
    cake_backend.cake_dense_gemm_det_train_projection_forward(v.x, v.w1, v.mid)
    cake_backend.cake_dense_gemm_det_train_projection_forward(v.mid, v.w2, v.y)
    torch.cuda.synchronize()
    assert torch.equal(v.y, first)


def test_prepared_pdl_chain_replays_in_a_cuda_graph(record_property):
    """Prepared launches fix ``enable_pdl`` at prepare time: a PDL chain of two prepared projections (the second reading the
    first's output) captured into a CUDA graph replays on new values written into the bound views.  Each draw writes
    its operands into the bound views and replays the graph; both outputs are judged against the naive BF16 tier over
    32 draws, the second on the activation the first wrote."""
    if not _device_supported():
        pytest.skip("requires a device with a registered generated instance")
    T = 512
    x, w1, w2 = _pdl_chain_inputs(T, 4096, 2048, 1024, SEED + 7)
    mid = torch.empty(T, 2048, device="cuda", dtype=torch.bfloat16)
    y = torch.empty(T, 1024, device="cuda", dtype=torch.bfloat16)
    first = cake_backend.cake_dense_gemm_det_train_projection_prepare(
        x, w1.t(), mid, enable_pdl=True
    )
    second = cake_backend.cake_dense_gemm_det_train_projection_prepare(
        mid, w2.t(), y, enable_pdl=True
    )
    first()
    second()
    torch.cuda.synchronize()
    stream = torch.cuda.Stream()
    stream.wait_stream(torch.cuda.current_stream())
    graph = torch.cuda.CUDAGraph()
    with torch.cuda.graph(graph, stream=stream):
        first()
        second()
    operands = SimpleNamespace(x=x, w1=w1, w2=w2, mid=mid)

    def draw(seed):
        fresh = _pdl_chain_inputs(T, 4096, 2048, 1024, seed)
        for dst, src in zip((x, w1, w2), fresh, strict=True):
            dst.copy_(src)
        return operands

    def launch(_operands):
        nan_fill([mid, y])
        graph.replay()
        torch.cuda.synchronize()
        return {"mid": mid, "y": y}

    judge_gemm(
        record_property,
        seed=SEED + 7,
        draw=draw,
        launch=launch,
        product=_d3_pdl_chain_product,
        after_launch=True,
    )


# The module selects the mode: torch.use_deterministic_algorithms (strict or warn_only) changes nothing.
@pytest.mark.parametrize("warn_only", [False, True])
def test_the_entry_points_run_unchanged_under_torch_deterministic_mode(warn_only):
    if arch_for(torch.device("cuda")) is None:
        pytest.skip("needs an SM100 / SM103 / SM107 GPU")
    device = torch.device("cuda", torch.cuda.current_device())
    m = cake_backend
    g = torch.Generator(device=device).manual_seed(0)
    T, K, N, R = 257, 6144, 576, 256  # the kv_a projection and the 256-expert router
    X = torch.randn(T, K, device=device, generator=g).bfloat16()
    W = (torch.randn(N, K, device=device, generator=g) * K**-0.5).bfloat16()
    G = torch.randn(T, N, device=device, generator=g).bfloat16()
    Xr = torch.randn(T, K, device=device, generator=g)
    Wr = torch.randn(R, K, device=device, generator=g) * K**-0.5
    Gr = torch.randn(T, R, device=device, generator=g)

    def run():
        return [
            m.cake_dense_gemm_det_train_projection_forward(X, W),
            m.cake_dense_gemm_det_train_projection_dgrad(G, W),
            m.cake_dense_gemm_det_train_projection_wgrad(G, X),
            m.cake_dense_gemm_det_train_router_forward(Xr, Wr),
            m.cake_dense_gemm_det_train_router_dgrad(Gr, Wr),
            m.cake_dense_gemm_det_train_router_wgrad(Gr, Xr),
        ]

    try:
        reference = run()
    except NotImplementedError as exc:  # a build without one of these programs
        pytest.skip(str(exc))
    previous = (
        torch.are_deterministic_algorithms_enabled(),
        torch.is_deterministic_algorithms_warn_only_enabled(),
    )
    try:
        torch.use_deterministic_algorithms(True, warn_only=warn_only)
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter("always")
            outputs = run()
            torch.cuda.synchronize(device)
    finally:
        torch.use_deterministic_algorithms(previous[0], warn_only=previous[1])
    assert [w for w in caught if "determinis" in str(w.message)] == []
    for got, want in zip(outputs, reference, strict=True):
        assert torch.equal(got, want)


# ---------------------------------------------------------------------------
# K1 weight-gradient chain plans (``CHAIN_RANGES_BY_SM``)
# ---------------------------------------------------------------------------


def _chain_wgrad_plan(N, T, M, sm_count, out_dtype=torch.float32, **knobs):
    """The planner's plan of the ``N -> M`` weight gradient at ``T`` tokens on an ``sm_107a`` part of ``sm_count`` SMs."""
    G = torch.empty(T, M, dtype=torch.bfloat16)
    X = torch.empty(T, N, dtype=torch.bfloat16)
    out = torch.empty(M, N, dtype=out_dtype)
    A, B, transposed = wgrad_views(
        G, X, arch="sm_107a", out_f32=out_dtype == torch.float32
    )
    plan, a_desc, b_desc, _o3 = cake_dense_gemm_det_train_projection_plan(
        A,
        B,
        out,
        sm_count=sm_count,
        l2_bytes=L2_BYTES,
        transposed_out=transposed,
        arch="sm_107a",
        **knobs,
    )
    return plan, (A, B, a_desc, b_desc)


def test_chain_ranges_plan_the_chain_program():
    """Inside a ``CHAIN_RANGES_BY_SM`` range the FP32 weight gradient plans the registered chain program: the caller's
    operands exchanged under the transposed store, three contiguous K-block chains, at most one CTA pair per two SMs
    and no workspace.  Outside a range, on another SM count, for a BF16 output, under a caller knob or the pure mirror
    the row keeps the planner's routing; an exact ``ROW_RULES`` key keeps precedence unless the range overrides it."""
    table = cake_backend.CHAIN_RANGES_BY_SM
    assert set(table) == {("sm_107a", 212), ("sm_107a", 216)}
    kernels = cake_jit.KERNELS["sm_107a"]
    checked = 0
    for (arch, sm_count), rows in table.items():
        for ident, ranges in rows.items():
            assert ident[:6] == (arch, True, True, True, False, False), ident
            N, M = ident[6], ident[7]
            for lo, hi, (block_n, chains), over_exact in ranges:
                template = cake_backend.chain_template(block_n, chains)
                assert template.startswith(cake_backend.CHAIN_TEMPLATE_PREFIX)
                assert template in kernels, template
                inside = sorted(
                    {lo, lo + 1, hi} | {t for t in (16231, 16384) if lo <= t <= hi}
                )
                for T in inside:
                    exact = (arch, True, True, True, False, False, N, T, M) in ROW_RULES
                    plan, (A, B, a_desc, b_desc) = _chain_wgrad_plan(N, T, M, sm_count)
                    if exact and not over_exact:
                        assert not isinstance(plan, cake_backend.ChainGemmPlan), (
                            N,
                            T,
                            M,
                        )
                        continue
                    assert isinstance(plan, cake_backend.ChainGemmPlan), (
                        sm_count,
                        N,
                        T,
                        M,
                        plan.template,
                    )
                    assert plan.template == template and (
                        plan.block_n,
                        plan.chains,
                    ) == (block_n, chains)
                    assert plan.swapped and not plan.transposed_out
                    assert (plan.launch_m, plan.launch_n, plan.K) == (N, M, T)
                    kb = -(-T // cake_backend.CHAIN_BLOCK_K)
                    assert plan.chain_bounds == tuple(
                        j * kb // chains for j in range(chains + 1)
                    )
                    assert all(
                        b > a
                        for a, b in zip(
                            plan.chain_bounds[:-1], plan.chain_bounds[1:], strict=True
                        )
                    )
                    tiles = -(-N // cake_backend.CHAIN_PAIR_ROWS) * -(-M // block_n)
                    assert plan.tiles == tiles and plan.grid == (
                        2 * min(tiles, sm_count // 2),
                        1,
                        1,
                    )
                    assert plan.ws_f32_elems == 0 and not plan.sk_units
                    assert cake_backend._k1_swapped(plan, A, B, transposed_out=False)
                    checked += 1
                for T in (lo - 1, hi + 1):
                    plan, _ = _chain_wgrad_plan(N, T, M, sm_count)
                    assert not isinstance(plan, cake_backend.ChainGemmPlan), (
                        sm_count,
                        N,
                        T,
                        M,
                    )
                T = min(max(16231, lo), hi)
                for kw in (dict(sk=False), dict(cta_rows=128), dict(_fallback=False)):
                    plan, _ = _chain_wgrad_plan(N, T, M, sm_count, **kw)
                    assert not isinstance(plan, cake_backend.ChainGemmPlan), (
                        N,
                        T,
                        M,
                        kw,
                    )
                plan, _ = _chain_wgrad_plan(N, T, M, sm_count, out_dtype=torch.bfloat16)
                assert not isinstance(plan, cake_backend.ChainGemmPlan), (N, T, M)
                for other in (148, 152, 208):
                    plan, _ = _chain_wgrad_plan(N, T, M, other)
                    assert not isinstance(plan, cake_backend.ChainGemmPlan), (
                        other,
                        N,
                        T,
                        M,
                    )
    assert checked
    # the exact keys of rows outside the table (4096 -> 512 / 4096 -> 1024) keep their programs at both SM counts
    for sm_count in (212, 216):
        for N, M in ((4096, 512), (4096, 1024)):
            for T in (16231, 16384):
                assert ("sm_107a", True, True, True, False, False, N, T, M) in ROW_RULES
                plan, _ = _chain_wgrad_plan(N, T, M, sm_count)
                assert not isinstance(plan, cake_backend.ChainGemmPlan), (
                    sm_count,
                    N,
                    T,
                    M,
                )


def test_chain_plan_of_exact_key_precedence(monkeypatch):
    """``chain_plan_of``: an exact ``ROW_RULES`` key of the row wins over a range without ``over_exact``; a range with it
    plans the chain program at the key's token count; chains that do not each get a K block are refused."""
    ident = ("sm_107a", True, True, True, False, False, 5120, 512)
    key = ("sm_107a", True, True, True, False, False, 5120, 16231, 512)
    assert key in ROW_RULES
    monkeypatch.setitem(
        cake_backend.CHAIN_RANGES_BY_SM,
        ("sm_107a", 216),
        {ident: ((64, 40961, (128, 3), False),)},
    )
    assert (
        cake_backend.chain_plan_of(
            "sm_107a", 216, 5120, 16231, 512, transposed_out=False
        )
        is None
    )
    assert cake_backend.chain_plan_of(
        "sm_107a", 216, 5120, 16232, 512, transposed_out=False
    ) == (128, 3)
    assert (
        cake_backend.chain_plan_of("sm_107a", 216, 5120, 64, 512, transposed_out=False)
        is None
    )
    assert cake_backend.chain_plan_of(
        "sm_107a", 216, 5120, 129, 512, transposed_out=False
    ) == (128, 3)
    assert (
        cake_backend.chain_plan_of(
            "sm_107a", 216, 5120, 16232, 512, transposed_out=True
        )
        is None
    )
    assert (
        cake_backend.chain_plan_of(
            "sm_107a", 208, 5120, 16232, 512, transposed_out=False
        )
        is None
    )
    monkeypatch.setitem(
        cake_backend.CHAIN_RANGES_BY_SM,
        ("sm_107a", 216),
        {ident: ((64, 40961, (128, 3), True),)},
    )
    assert cake_backend.chain_plan_of(
        "sm_107a", 216, 5120, 16231, 512, transposed_out=False
    ) == (128, 3)
    assert not cake_backend.chains_fit(3, 128) and cake_backend.chains_fit(3, 129)


@pytest.mark.parametrize("N, M", [(5120, 1024), (5120, 512)])
@pytest.mark.parametrize("T", [961, 4096])
def test_chain_wgrad_matches_fp64_and_repeats_bitwise(
    N, M, T, monkeypatch, record_property
):
    """On an ``sm_107a`` part of a ``CHAIN_RANGES_BY_SM`` SM count the chain plan of the FP32 weight gradient is judged
    against the naive BF16 tier over 32 draws (odd K-block counts included), and on the last draw its prepared
    launch, rerun over NaN-poisoned outputs, gives the bits of the judged launch; elsewhere it skips."""
    if not _device_supported():
        pytest.skip(
            "requires a device with a registered generated instance "
            f"(compute capability {_registered_capabilities()})"
        )
    device = torch.device("cuda")
    if arch_for(device) != "sm_107a":
        pytest.skip(f"an sm_107a plan; the device is {arch_for(device)}")
    sm_count = _sm_count()
    choice = cake_backend.chain_plan_of(
        "sm_107a", sm_count, N, T, M, transposed_out=False
    )
    if choice is None:
        pytest.skip(f"no chain range for {N} -> {M} at T {T} on {sm_count} SMs")
    _require_program(cake_backend.chain_template(*choice))
    monkeypatch.setattr(cake_backend, "_DUMMIES", {})
    G, X = _d3_wgrad_operands(T, M, N, SEED + 11, device)
    out = torch.full((M, N), float("nan"), dtype=torch.float32, device=device)
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
    prepared = cake_dense_gemm_det_train_projection_wgrad_prepare(G, X, out)
    assert isinstance(prepared.plan, cake_backend.ChainGemmPlan), prepared.template

    def launch(_operands):
        nan_fill([out])
        prepared.launch()
        torch.cuda.synchronize()
        return {"out": out}

    def product(operands, dtype):
        g, x = operands
        return {"out": torch.matmul(g.to(dtype).t(), x.to(dtype))}

    judge_gemm(
        record_property,
        seed=SEED + 11,
        draw=_d3_wgrad_draw(G, X),
        launch=launch,
        product=product,
    )
    first = out.clone()
    for _ in range(REPEATS):
        out.fill_(float("nan"))
        prepared.launch()
        torch.cuda.synchronize()
        assert torch.equal(out.view(torch.int32), first.view(torch.int32))
    cake_backend.cake_dense_gemm_det_train_convenience_cache_clear()
